    { const char * tb_v2686 = "// авария ядра: красным на экран и в порт, потом стоп\n"; *(const char * *)tb_grow(v_lines) = tb_v2686; }
    { const char * tb_v2687 = "__attribute__((noreturn)) static void tb_panic(const char *what, uint64_t a, uint64_t b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2687; }
