    { const char * tb_v2695 = "// --- таблица сегментов x86-64: код 64 бита, данные, задача процессора (TSS, 16 байт) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v2695; }
    { const char * tb_v2696 = "// у каждого ядра процессора свой TSS (две записи по 8 байт): номер сегмента 0x18 + 16 × ядро\n"; *(const char * *)tb_grow(v_lines) = tb_v2696; }
