    { const char * tb_v2712 = "        \".set tb_v, 0\\n.rept 50\\n.balign 16\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2712; }
    { const char * tb_v2713 = "        \".if (tb_v == 8) || (tb_v == 10) || (tb_v == 11) || (tb_v == 12) || (tb_v == 13) || (tb_v == 14) || (tb_v == 17) || (tb_v == 21)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2713; }
    { const char * tb_v2714 = "        \".else\\npushq $0\\n.endif\\npushq $tb_v\\njmp tb_isr_common\\n.set tb_v, tb_v + 1\\n.endr\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2714; }
    { const char * tb_v2715 = "        \"tb_isr_common:\\ncld\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2715; }
    { const char * tb_v2716 = "        \"pushq %rax\\npushq %rcx\\npushq %rdx\\npushq %rbx\\npushq %rbp\\npushq %rsi\\npushq %rdi\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2716; }
    { const char * tb_v2717 = "        \"pushq %r8\\npushq %r9\\npushq %r10\\npushq %r11\\npushq %r12\\npushq %r13\\npushq %r14\\npushq %r15\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2717; }
    { const char * tb_v2718 = "        \"subq $512, %rsp\\nfxsave (%rsp)\\nmovq %rsp, %rdi\\ncall tb_isr\\nmovq %rax, %rsp\\ncall tb_switch_done\\nfxrstor (%rsp)\\naddq $512, %rsp\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2718; }
    { const char * tb_v2719 = "        \"popq %r15\\npopq %r14\\npopq %r13\\npopq %r12\\npopq %r11\\npopq %r10\\npopq %r9\\npopq %r8\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2719; }
