    { const char * tb_v2964 = "// ---- модули (файлы, которые загрузчик положил рядом с ядром: qemu -initrd \"a.oapp,b.oapp\") ----\n"; *(const char * *)tb_grow(v_lines) = tb_v2964; }
    { const char * tb_v2965 = "// у Multiboot: флаг 3 — есть модули; mbi[5] — сколько, mbi[6] — где список (по 16 байт: начало, конец, имя, 0)\n"; *(const char * *)tb_grow(v_lines) = tb_v2965; }
