    { const char * tb_v2968 = "    *n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2968; }
    { const char * tb_v2969 = "    if (tb_boot_magic != 0x2BADB002u || mbi == 0 || !(mbi[0] & 8)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2969; }
    { const char * tb_v2970 = "    *n = mbi[5];\n"; *(const char * *)tb_grow(v_lines) = tb_v2970; }
    { const char * tb_v2971 = "    return (uint32_t *)(uintptr_t)mbi[6];\n"; *(const char * *)tb_grow(v_lines) = tb_v2971; }
    { const char * tb_v2972 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2972; }
    { const char * tb_v2973 = "TB_API uint64_t tb_mods_top(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2973; }
    { const char * tb_v2974 = "    long long n; uint32_t *m = tb_mods(&n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2974; }
    { const char * tb_v2975 = "    uint64_t top = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2975; }
