    { const char * tb_v2987 = "// таблица имён ядра (её заполняет компоновщик elf_link.py): по алфавиту, 16 байт на имя —\n"; *(const char * *)tb_grow(v_lines) = tb_v2987; }
    { const char * tb_v2988 = "// адрес, где имя (от начала таблицы), длина имени. Программы Омниума находят по ней функции ядра\n"; *(const char * *)tb_grow(v_lines) = tb_v2988; }
    { const char * tb_v2989 = "TB_API volatile uint64_t tb_ksym_tab __attribute__((used)) = 1, tb_ksym_n __attribute__((used)) = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2989; }
    { const char * tb_v2990 = "TB_API long long tb_kernel_symbol(const char *nm) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2990; }
    { const char * tb_v2991 = "    uint64_t t = tb_ksym_tab;\n"; *(const char * *)tb_grow(v_lines) = tb_v2991; }
    { const char * tb_v2992 = "    long long lo = 0, hi = (long long)tb_ksym_n - 1, len = (long long)strlen(nm);\n"; *(const char * *)tb_grow(v_lines) = tb_v2992; }
    { const char * tb_v2993 = "    if (t <= 1) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2993; }
    { const char * tb_v2994 = "    while (lo <= hi) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2994; }
    { const char * tb_v2995 = "        long long mid = (lo + hi) / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2995; }
    { const char * tb_v2996 = "        const uint64_t *e = (const uint64_t *)(uintptr_t)(t + 16 * mid);\n"; *(const char * *)tb_grow(v_lines) = tb_v2996; }
    { const char * tb_v2997 = "        uint32_t off = (uint32_t)e[1], n = (uint32_t)(e[1] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v2997; }
    { const char * tb_v2998 = "        int r = memcmp((const char *)(uintptr_t)(t + off), nm, (size_t)(n < len ? n : len));\n"; *(const char * *)tb_grow(v_lines) = tb_v2998; }
    { const char * tb_v2999 = "        if (r == 0) r = n < len ? -1 : n > len ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2999; }
