    { const char * tb_v3081 = "// --- владение памятью (обменная куча, как в старой Омниум): у куска один хозяин — клетка.\n"; *(const char * *)tb_grow(v_lines) = tb_v3081; }
    { const char * tb_v3082 = "// Что уходит из клетки (аргументы background, текст в канале, список через move), становится\n"; *(const char * *)tb_grow(v_lines) = tb_v3082; }
    { const char * tb_v3083 = "// ничьим (метка 0, «ядро») или переходит получателю. Упала клетка — ядро возвращает всё, что\n"; *(const char * *)tb_grow(v_lines) = tb_v3083; }
    { const char * tb_v3084 = "// у неё осталось: этого больше никто не видит.\n"; *(const char * *)tb_grow(v_lines) = tb_v3084; }
    { const char * tb_v3085 = "TB_API int tb_is_piece(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3085; }
    { const char * tb_v3086 = "    const unsigned char *u = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3086; }
    { const char * tb_v3087 = "    if (!p || ((uintptr_t)p & 15) || u < tb_heap + 16 || u >= tb_heap + tb_heap_top) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3087; }
