    { const char * tb_v3103 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v3103; }
    { const char * tb_v3104 = "    if (tb_is_piece(p)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3104; }
