    { const char * tb_v3113 = "TB_API long long tb_cell_reclaim(uint64_t tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3113; }
    { const char * tb_v3114 = "    long long got = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3114; }
