    { const char * tb_v3237 = "// --- несколько ядер процессора («звёзды») ---\n"; *(const char * *)tb_grow(v_lines) = tb_v3237; }
    { const char * tb_v3238 = "// Какие ядра есть — из таблицы ACPI «APIC» (MADT). Каждое будим так: INIT, потом дважды\n"; *(const char * *)tb_grow(v_lines) = tb_v3238; }
    { const char * tb_v3239 = "// SIPI с адресом 0x8000; там маленький код (ниже) переводит ядро из 16 бит сразу в 64\n"; *(const char * *)tb_grow(v_lines) = tb_v3239; }
    { const char * tb_v3240 = "// и прыгает в tb_ap_main со своим стеком.\n"; *(const char * *)tb_grow(v_lines) = tb_v3240; }
    { const char * tb_v3241 = "TB_API int tb_apic_ids[TB_NCPU];\n"; *(const char * *)tb_grow(v_lines) = tb_v3241; }
    { const char * tb_v3242 = "// таблицы ACPI лежат выше памяти, которую назвал загрузчик: показываем их кусок 2 МБ (только читать)\n"; *(const char * *)tb_grow(v_lines) = tb_v3242; }
    { const char * tb_v3243 = "TB_API void tb_map_2m(uint64_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3243; }
    { const char * tb_v3244 = "    if (a >= (4ull << 30) || a < (uint64_t)(uintptr_t)tb_heap_area) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3244; }
    { const char * tb_v3245 = "    uint64_t *e = &tb_pdir[a >> 30][(a >> 21) & 511];\n"; *(const char * *)tb_grow(v_lines) = tb_v3245; }
