    { const char * tb_v3251 = "TB_API int tb_find_cpus(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3251; }
    { const char * tb_v3252 = "    unsigned char *rsdp = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3252; }
