    { const char * tb_v3254 = "        if (memcmp((void *)(uintptr_t)a, \"RSD PTR \", 8) == 0) rsdp = (unsigned char *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v3254; }
    { const char * tb_v3255 = "    if (!rsdp) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3255; }
