    { const char * tb_v3258 = "    uint32_t len = *(uint32_t *)(rsdt + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3258; }
    { const char * tb_v3259 = "    int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3259; }
