    { const char * tb_v3264 = "        uint32_t tl = *(uint32_t *)(t + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3264; }
    { const char * tb_v3265 = "        for (uint32_t e = 44; e + 2 <= tl && n < TB_NCPU; e += t[e + 1]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3265; }
