    { const char * tb_v3548 = "    return w;\n"; *(const char * *)tb_grow(v_lines) = tb_v3548; }
    { const char * tb_v3549 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3549; }
    { const char * tb_v3550 = "TB_API int tb_win_system(const char *command) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3550; }
    { const char * tb_v3551 = "    wchar_t *c = tb_win_cmd(command);\n"; *(const char * *)tb_grow(v_lines) = tb_v3551; }
    { const char * tb_v3552 = "    int r = c ? _wsystem(c) : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3552; }
    { const char * tb_v3553 = "    free(c);\n"; *(const char * *)tb_grow(v_lines) = tb_v3553; }
    { const char * tb_v3554 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3554; }
    { const char * tb_v3555 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3555; }
    { const char * tb_v3556 = "TB_API FILE *tb_win_popen(const char *command, const char *mode) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3556; }
    { const char * tb_v3557 = "    wchar_t *c = tb_win_cmd(command), *m = tb_wide(mode);\n"; *(const char * *)tb_grow(v_lines) = tb_v3557; }
    { const char * tb_v3558 = "    FILE *f = c && m ? _wpopen(c, m) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3558; }
    { const char * tb_v3559 = "    free(c); free(m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3559; }
    { const char * tb_v3560 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v3560; }
    { const char * tb_v3561 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3561; }
    { const char * tb_v3562 = "// папка: _wopendir / _wreaddir, имена — в UTF-8\n"; *(const char * *)tb_grow(v_lines) = tb_v3562; }
    { const char * tb_v3563 = "struct tb_win_dirent { char d_name[MAX_PATH * 4]; };\n"; *(const char * *)tb_grow(v_lines) = tb_v3563; }
    { const char * tb_v3564 = "typedef struct { _WDIR *d; struct tb_win_dirent e; } tb_win_dir;\n"; *(const char * *)tb_grow(v_lines) = tb_v3564; }
    { const char * tb_v3565 = "TB_API tb_win_dir *tb_win_opendir(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3565; }
    { const char * tb_v3566 = "    wchar_t *p = tb_wide(path);\n"; *(const char * *)tb_grow(v_lines) = tb_v3566; }
    { const char * tb_v3567 = "    _WDIR *d = p ? _wopendir(p) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3567; }
    { const char * tb_v3568 = "    free(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3568; }
    { const char * tb_v3569 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3569; }
    { const char * tb_v3570 = "    tb_win_dir *r = calloc(1, sizeof *r);\n"; *(const char * *)tb_grow(v_lines) = tb_v3570; }
    { const char * tb_v3571 = "    if (!r) { _wclosedir(d); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3571; }
    { const char * tb_v3572 = "    r->d = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3572; }
    { const char * tb_v3573 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3573; }
    { const char * tb_v3574 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3574; }
    { const char * tb_v3575 = "TB_API struct tb_win_dirent *tb_win_readdir(tb_win_dir *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3575; }
    { const char * tb_v3576 = "    struct _wdirent *e = _wreaddir(d->d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3576; }
    { const char * tb_v3577 = "    if (!e) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3577; }
    { const char * tb_v3578 = "    if (WideCharToMultiByte(CP_UTF8, 0, e->d_name, -1, d->e.d_name, sizeof d->e.d_name, 0, 0) <= 0) d->e.d_name[0] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3578; }
    { const char * tb_v3579 = "    return &d->e;\n"; *(const char * *)tb_grow(v_lines) = tb_v3579; }
    { const char * tb_v3580 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3580; }
    { const char * tb_v3581 = "TB_API int tb_win_closedir(tb_win_dir *d) { _wclosedir(d->d); free(d); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3581; }
    { const char * tb_v3582 = "// цвет в консоли — только если удалось включить ESC-последовательности (Windows 10+)\n"; *(const char * *)tb_grow(v_lines) = tb_v3582; }
