    { const char * tb_v3592 = "    GetSystemInfo(&si);\n"; *(const char * *)tb_grow(v_lines) = tb_v3592; }
    { const char * tb_v3593 = "    return (long)si.dwNumberOfProcessors;\n"; *(const char * *)tb_grow(v_lines) = tb_v3593; }
