    { const char * tb_v3598 = "#define rmdir(p) tb_win_rmdir(p)\n"; *(const char * *)tb_grow(v_lines) = tb_v3598; }
    { const char * tb_v3599 = "#define unlink(p) tb_win_unlink(p)\n"; *(const char * *)tb_grow(v_lines) = tb_v3599; }
