    { const char * tb_v4554 = "// ---------- падение по памяти: понятное сообщение вместо «Segmentation fault» ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4554; }
    { const char * tb_v4555 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v4555; }
    { const char * tb_v4556 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v4556; }
    { const char * tb_v4557 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v4557; }
    { const char * tb_v4558 = "#include <signal.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4558; }
    { const char * tb_v4559 = "#include <sys/resource.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4559; }
    { const char * tb_v4560 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4560; }
    { const char * tb_v4561 = "// На Windows нет сигналов и sigaltstack: переполнение стека ловит обработчик\n"; *(const char * *)tb_grow(v_lines) = tb_v4561; }
    { const char * tb_v4562 = "// исключений (tb_guard_init ниже), а место для него в конце стека даёт\n"; *(const char * *)tb_grow(v_lines) = tb_v4562; }
    { const char * tb_v4563 = "// SetThreadStackGuarantee. Этот sigaltstack только помнит память потока,\n"; *(const char * *)tb_grow(v_lines) = tb_v4563; }
    { const char * tb_v4564 = "// чтобы tb_tramp_run мог её отдать, и просит у Windows запас стека.\n"; *(const char * *)tb_grow(v_lines) = tb_v4564; }
    { const char * tb_v4565 = "typedef struct { void *ss_sp; size_t ss_size; int ss_flags; } stack_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4565; }
    { const char * tb_v4566 = "#define SS_DISABLE 4\n"; *(const char * *)tb_grow(v_lines) = tb_v4566; }
    { const char * tb_v4567 = "TB_API _Thread_local void *tb_win_alt;\n"; *(const char * *)tb_grow(v_lines) = tb_v4567; }
    { const char * tb_v4568 = "TB_API int sigaltstack(const stack_t *ss, stack_t *old) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4568; }
    { const char * tb_v4569 = "    if (old) { old->ss_sp = tb_win_alt; old->ss_size = 0; old->ss_flags = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4569; }
    { const char * tb_v4570 = "    if (ss) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4570; }
    { const char * tb_v4571 = "        tb_win_alt = (ss->ss_flags & SS_DISABLE) ? 0 : ss->ss_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4571; }
    { const char * tb_v4572 = "        if (!(ss->ss_flags & SS_DISABLE)) { ULONG g = 65536; SetThreadStackGuarantee(&g); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4572; }
    { const char * tb_v4573 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4573; }
    { const char * tb_v4574 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4574; }
    { const char * tb_v4575 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4575; }
    { const char * tb_v4576 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4576; }
    { const char * tb_v4577 = "// у каждого потока своё: где начинается его стек и сколько в нём места\n"; *(const char * *)tb_grow(v_lines) = tb_v4577; }
    { const char * tb_v4578 = "TB_API _Thread_local char *tb_main_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4578; }
