    { const char * tb_v5180 = "TB_API double tb_gnow(void) { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec * 1e3 + ts.tv_nsec / 1e6; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5180; }
    { const char * tb_v5181 = "TB_API void tb_gc_collect(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5181; }
    { const char * tb_v5182 = "    tb_gruns++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5182; }
    { const char * tb_v5183 = "    double t0 = tb_gstats ? tb_gnow() : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5183; }
