    { const char * tb_v5189 = "    for (int c = 0; c < TB_GNC; c++) { tb_gavail[0][c] = 0; tb_gavail[1][c] = 0; keep_empty[c] = 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5189; }
