    { const char * tb_v5208 = "            char *b = pg->start + i * pg->bsize;\n"; *(const char * *)tb_grow(v_lines) = tb_v5208; }
    { const char * tb_v5209 = "            if (pg->fl[i] == 3) { pg->fl[i] = 1; used++; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5209; }
    { const char * tb_v5210 = "            if (pg->fl[i] & 1) memset(b, 0, pg->bsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v5210; }
