    { const char * tb_v5216 = "            tb_gmap_remove(pg, TB_GPG);\n"; *(const char * *)tb_grow(v_lines) = tb_v5216; }
    { const char * tb_v5217 = "            // страница — в запас, чистой (в свободных блоках лежали ссылки на соседей)\n"; *(const char * *)tb_grow(v_lines) = tb_v5217; }
