    { const char * tb_v5345 = "// ---------- list bool: по одному биту на элемент (в 8 раз меньше памяти) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5345; }
    { const char * tb_v5346 = "// тот же tb_list: len и cap — в битах, size = 0, data — слова по 64 бита\n"; *(const char * *)tb_grow(v_lines) = tb_v5346; }
    { const char * tb_v5347 = "TB_API tb_list *tb_bits_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5347; }
