    { const char * tb_v5390 = "// N одинаковых битов в конец (repeat N times: flags.add(true))\n"; *(const char * *)tb_grow(v_lines) = tb_v5390; }
    { const char * tb_v5391 = "TB_API void tb_bfill(tb_list *l, long long n, _Bool v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5391; }
    { const char * tb_v5392 = "    if (n <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5392; }
    { const char * tb_v5393 = "    if (l->cap < 0) tb_crash(0, \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5393; }
    { const char * tb_v5394 = "    long long need = l->len + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5394; }
    { const char * tb_v5395 = "    if (need > l->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5395; }
