    { const char * tb_v5470 = "// ---------- буквы: len, s[i], cut, find, code, char и each считают буквы, а не байты ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5470; }
    { const char * tb_v5471 = "// Текст хранится в UTF-8: латинская буква — 1 байт, русская — 2, иероглиф — 3, смайлик — 4.\n"; *(const char * *)tb_grow(v_lines) = tb_v5471; }
    { const char * tb_v5472 = "// Байт, который не складывается в букву (испорченный UTF-8, байты с диска), — сам себе буква.\n"; *(const char * *)tb_grow(v_lines) = tb_v5472; }
    { const char * tb_v5473 = "TB_INL long long tb_u8n(const unsigned char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5473; }
    { const char * tb_v5474 = "    unsigned char b = p[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v5474; }
    { const char * tb_v5475 = "    if (b < 0xC2 || b > 0xF4) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5475; }
    { const char * tb_v5476 = "    long long need = b < 0xE0 ? 2 : b < 0xF0 ? 3 : 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v5476; }
    { const char * tb_v5477 = "    for (long long k = 1; k < need; k++) if ((p[k] & 0xC0) != 0x80) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5477; }
    { const char * tb_v5478 = "    return need;\n"; *(const char * *)tb_grow(v_lines) = tb_v5478; }
    { const char * tb_v5479 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5479; }
    { const char * tb_v5480 = "// сколько букв в первых nb байтах\n"; *(const char * *)tb_grow(v_lines) = tb_v5480; }
    { const char * tb_v5481 = "TB_API long long tb_u8count(const char *s, long long nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5481; }
    { const char * tb_v5482 = "    const unsigned char *p = (const unsigned char *)s, *e = p + nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v5482; }
    { const char * tb_v5483 = "    long long n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5483; }
    { const char * tb_v5484 = "    while (p < e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5484; }
    { const char * tb_v5485 = "        if (*p < 0x80) { p++; n++; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5485; }
    { const char * tb_v5486 = "        long long k = tb_u8n(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5486; }
    { const char * tb_v5487 = "        if (p + k > e) k = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5487; }
    { const char * tb_v5488 = "        p += k; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5488; }
    { const char * tb_v5489 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5489; }
    { const char * tb_v5490 = "    return n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5490; }
    { const char * tb_v5491 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5491; }
    { const char * tb_v5492 = "// память о последних текстах: адрес, байты, буквы и где мы стояли (буква li начинается с байта bi).\n"; *(const char * *)tb_grow(v_lines) = tb_v5492; }
    { const char * tb_v5493 = "// s[i] подряд в цикле — шаг вперёд от прошлого места, а не счёт с начала.\n"; *(const char * *)tb_grow(v_lines) = tb_v5493; }
    { const char * tb_v5494 = "typedef struct { const char *p; long long nb, nl, li, bi; } tb_u8slot;\n"; *(const char * *)tb_grow(v_lines) = tb_v5494; }
    { const char * tb_v5495 = "TB_API _Thread_local tb_u8slot tb_u8c[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v5495; }
    { const char * tb_v5496 = "TB_API _Thread_local int tb_u8c_next;\n"; *(const char * *)tb_grow(v_lines) = tb_v5496; }
    { const char * tb_v5497 = "TB_INL void tb_u8c_clear(void) { for (int k = 0; k < 4; k++) tb_u8c[k].p = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5497; }
    { const char * tb_v5498 = "// nb < 0: длину в байтах посчитать (текст не меняется); nb >= 0: текст, в который дописывают\n"; *(const char * *)tb_grow(v_lines) = tb_v5498; }
    { const char * tb_v5499 = "TB_API tb_u8slot *tb_u8info(const char *s, long long nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5499; }
    { const char * tb_v5500 = "    for (int k = 0; k < 4; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5500; }
    { const char * tb_v5501 = "        tb_u8slot *c = &tb_u8c[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v5501; }
    { const char * tb_v5502 = "        if (c->p != s) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v5502; }
    { const char * tb_v5503 = "        if (nb < 0 || nb == c->nb) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5503; }
    { const char * tb_v5504 = "        if (nb > c->nb) {   // дописали в конец: досчитать только новое\n"; *(const char * *)tb_grow(v_lines) = tb_v5504; }
    { const char * tb_v5505 = "            // последняя буква могла быть недописанной: пересчитать с её начала (не дальше 3 байт назад)\n"; *(const char * *)tb_grow(v_lines) = tb_v5505; }
    { const char * tb_v5506 = "            long long from = c->nb, b = c->nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v5506; }
    { const char * tb_v5507 = "            while (b > 0 && c->nb - b < 3 && ((unsigned char)s[b - 1] & 0xC0) == 0x80) b--;\n"; *(const char * *)tb_grow(v_lines) = tb_v5507; }
    { const char * tb_v5508 = "            if (b > 0 && (unsigned char)s[b - 1] >= 0xC0) from = b - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5508; }
    { const char * tb_v5509 = "            c->nl = c->nl - tb_u8count(s + from, c->nb - from) + tb_u8count(s + from, nb - from);\n"; *(const char * *)tb_grow(v_lines) = tb_v5509; }
    { const char * tb_v5510 = "            c->nb = nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v5510; }
    { const char * tb_v5511 = "            if (c->bi > from) { c->li = 0; c->bi = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5511; }
