    { const char * tb_v5554 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v5554; }
    { const char * tb_v5555 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5555; }
    { const char * tb_v5556 = "// s[i]: буква номер i; n — длина в байтах, если компилятор её знает (текст, в который дописывают), иначе -1\n"; *(const char * *)tb_grow(v_lines) = tb_v5556; }
    { const char * tb_v5557 = "TB_API const char *tb_char_at(const char *s, long long i, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5557; }
    { const char * tb_v5558 = "    tb_u8slot *c = tb_u8info(s, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v5558; }
    { const char * tb_v5559 = "    if (i < 0 || i >= c->nl) tb_crash(line, \"номер за пределами текста\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5559; }
    { const char * tb_v5560 = "    if (c->nl == c->nb) return tb_chr((unsigned char)s[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v5560; }
    { const char * tb_v5561 = "    long long b = tb_u8off(c, i);\n"; *(const char * *)tb_grow(v_lines) = tb_v5561; }
