    { const char * tb_v5564 = "    return tb_u8text(s + b, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v5564; }
    { const char * tb_v5565 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5565; }
    { const char * tb_v5566 = "// each ch in s: буква с байта *i; *i становится последним байтом буквы (цикл сам прибавит 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v5566; }
    { const char * tb_v5567 = "TB_API const char *tb_u8take(const char *s, long long *i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5567; }
    { const char * tb_v5568 = "    const unsigned char *p = (const unsigned char *)s + *i;\n"; *(const char * *)tb_grow(v_lines) = tb_v5568; }
    { const char * tb_v5569 = "    if (*p < 0x80) return tb_chr(*p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5569; }
