    { const char * tb_v5574 = "// s += b: дописать в конец своей памяти s, а не собирать третий текст из двух.\n"; *(const char * *)tb_grow(v_lines) = tb_v5574; }
    { const char * tb_v5575 = "// *rl — длина s в своей памяти (-1: своей памяти нет, s могли сохранить где-то ещё — сначала копия),\n"; *(const char * *)tb_grow(v_lines) = tb_v5575; }
    { const char * tb_v5576 = "// *rc — сколько там места.\n"; *(const char * *)tb_grow(v_lines) = tb_v5576; }
    { const char * tb_v5577 = "TB_API void tb_app_n(const char **p, long long *rl, long long *rc, const char *b, long long lb);\n"; *(const char * *)tb_grow(v_lines) = tb_v5577; }
    { const char * tb_v5578 = "// число цифрами в конец буфера d[24]: вернёт начало цифр, длину — в *n\n"; *(const char * *)tb_grow(v_lines) = tb_v5578; }
    { const char * tb_v5579 = "TB_INL const char *tb_digits(long long x, char *d, long long *n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5579; }
    { const char * tb_v5580 = "    unsigned long long u = x < 0 ? 0ULL - (unsigned long long)x : (unsigned long long)x;\n"; *(const char * *)tb_grow(v_lines) = tb_v5580; }
    { const char * tb_v5581 = "    char *p = d + 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v5581; }
