    { const char * tb_v5994 = "    const char *e = tb_js_skip(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5994; }
    { const char * tb_v5995 = "    if (!e) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5995; }
