    { const char * tb_v6514 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6514; }
    { const char * tb_v6515 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6515; }
    { const char * tb_v6516 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v6516; }
    { const char * tb_v6517 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6517; }
    { const char * tb_v6518 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6518; }
