    { const char * tb_v6521 = "TB_API void *tb_obj_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6521; }
    { const char * tb_v6522 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6522; }
    { const char * tb_v6523 = "    return tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6523; }
    { const char * tb_v6524 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6524; }
    { const char * tb_v6525 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6525; }
    { const char * tb_v6526 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6526; }
    { const char * tb_v6527 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v6527; }
    { const char * tb_v6528 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6528; }
    { const char * tb_v6529 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6529; }
