    { const char * tb_v6531 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6531; }
    { const char * tb_v6532 = "// a = service f(): в программе с ОС служба — тот же background (запас памяти есть только в ядре)\n"; *(const char * *)tb_grow(v_lines) = tb_v6532; }
    { const char * tb_v6533 = "TB_API void tb_service_start(tb_task *t, void *(*run)(void *), void *arg) { tb_task_start(t, run, arg); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6533; }
    { const char * tb_v6534 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v6534; }
    { const char * tb_v6535 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6535; }
    { const char * tb_v6536 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6536; }
    { const char * tb_v6537 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v6537; }
    { const char * tb_v6538 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6538; }
    { const char * tb_v6539 = "// a.crashed: в обычной программе падение задачи роняет всю программу — сюда доходят только целые\n"; *(const char * *)tb_grow(v_lines) = tb_v6539; }
    { const char * tb_v6540 = "TB_API _Bool tb_crashed(tb_task *t) { tb_wait(t); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6540; }
    { const char * tb_v6541 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6541; }
    { const char * tb_v6542 = "TB_API int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6542; }
    { const char * tb_v6543 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6543; }
    { const char * tb_v6544 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v6544; }
    { const char * tb_v6545 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6545; }
    { const char * tb_v6546 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v6546; }
    { const char * tb_v6547 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6547; }
    { const char * tb_v6548 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v6548; }
    { const char * tb_v6549 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6549; }
    { const char * tb_v6550 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6550; }
    { const char * tb_v6551 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6551; }
    { const char * tb_v6552 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6552; }
    { const char * tb_v6553 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v6553; }
    { const char * tb_v6554 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6554; }
    { const char * tb_v6555 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6555; }
    { const char * tb_v6556 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v6556; }
    { const char * tb_v6557 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6557; }
    { const char * tb_v6558 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6558; }
    { const char * tb_v6559 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v6559; }
    { const char * tb_v6560 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6560; }
