    { const char * tb_v6562 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6562; }
    { const char * tb_v6563 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6563; }
    { const char * tb_v6564 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6564; }
    { const char * tb_v6565 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v6565; }
    { const char * tb_v6566 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v6566; }
    { const char * tb_v6567 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v6567; }
    { const char * tb_v6568 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v6568; }
    { const char * tb_v6569 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6569; }
    { const char * tb_v6570 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v6570; }
    { const char * tb_v6571 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v6571; }
    { const char * tb_v6572 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6572; }
    { const char * tb_v6573 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6573; }
    { const char * tb_v6574 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6574; }
    { const char * tb_v6575 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6575; }
    { const char * tb_v6576 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v6576; }
    { const char * tb_v6577 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v6577; }
    { const char * tb_v6578 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6578; }
    { const char * tb_v6579 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v6579; }
    { const char * tb_v6580 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6580; }
    { const char * tb_v6581 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6581; }
    { const char * tb_v6582 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v6582; }
    { const char * tb_v6583 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6583; }
    { const char * tb_v6584 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6584; }
    { const char * tb_v6585 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v6585; }
    { const char * tb_v6586 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v6586; }
    { const char * tb_v6587 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v6587; }
    { const char * tb_v6588 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v6588; }
    { const char * tb_v6589 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v6589; }
    { const char * tb_v6590 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6590; }
    { const char * tb_v6591 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6591; }
    { const char * tb_v6592 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6592; }
    { const char * tb_v6593 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6593; }
    { const char * tb_v6594 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6594; }
    { const char * tb_v6595 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6595; }
    { const char * tb_v6596 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v6596; }
    { const char * tb_v6597 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v6597; }
    { const char * tb_v6598 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v6598; }
    { const char * tb_v6599 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6599; }
    { const char * tb_v6600 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6600; }
    { const char * tb_v6601 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v6601; }
    { const char * tb_v6602 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6602; }
    { const char * tb_v6603 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v6603; }
    { const char * tb_v6604 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6604; }
    { const char * tb_v6605 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6605; }
    { const char * tb_v6606 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v6606; }
    { const char * tb_v6607 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v6607; }
    { const char * tb_v6608 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v6608; }
    { const char * tb_v6609 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v6609; }
    { const char * tb_v6610 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6610; }
    { const char * tb_v6611 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v6611; }
    { const char * tb_v6612 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v6612; }
    { const char * tb_v6613 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v6613; }
    { const char * tb_v6614 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6614; }
    { const char * tb_v6615 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6615; }
    { const char * tb_v6616 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v6616; }
    { const char * tb_v6617 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6617; }
    { const char * tb_v6618 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6618; }
    { const char * tb_v6619 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6619; }
    { const char * tb_v6620 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6620; }
    { const char * tb_v6621 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6621; }
    { const char * tb_v6622 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6622; }
    { const char * tb_v6623 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v6623; }
