    { const char * tb_v6814 = "    if (h->magic == TB_MEM_DEAD) { snprintf(buf, sizeof buf, \"%s: блок уже освобождён\", who); tb_crash(line, buf); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6814; }
    { const char * tb_v6815 = "    if (h->magic != TB_MEM_LIVE) { snprintf(buf, sizeof buf, \"%s: это не адрес из new_mem или блок уже освобождён (точнее покажет TB_MEM_CHECK=1)\", who); tb_crash(line, buf); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6815; }
