    { const char * tb_v6818 = "// TB_MEM_CHECK: блок не отдаётся обратно, а помечается — чтобы поймать чтение после free_mem\n"; *(const char * *)tb_grow(v_lines) = tb_v6818; }
    { const char * tb_v6819 = "static void tb_mem_bury(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6819; }
