    { const char * tb_v6826 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6826; }
    { const char * tb_v6827 = "// free_mem(адрес): отдать блок; free_mem(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v6827; }
    { const char * tb_v6828 = "TB_API void tb_free_mem(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6828; }
    { const char * tb_v6829 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6829; }
