    { const char * tb_v6835 = "// grow_mem(адрес, байт): блок нового размера (данные сохраняются, новое место — нули); адрес может стать другим\n"; *(const char * *)tb_grow(v_lines) = tb_v6835; }
    { const char * tb_v6836 = "TB_API long long tb_grow_mem(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6836; }
