    { const char * tb_v6841 = "    uint64_t old = h->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6841; }
    { const char * tb_v6842 = "    if (tb_memchk()) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6842; }
