    { const char * tb_v6851 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6851; }
    { const char * tb_v6852 = "    tb_memh *q = realloc(h, sizeof(tb_memh) + (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6852; }
    { const char * tb_v6853 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6853; }
    { const char * tb_v6854 = "    tb_mem_soft(-1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6854; }
