    { const char * tb_v6856 = "    if (!q) { tb_err = \"grow_mem: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6856; }
    { const char * tb_v6857 = "    if ((uint64_t)n > old) memset((unsigned char *)(q + 1) + old, 0, (size_t)((uint64_t)n - old));\n"; *(const char * *)tb_grow(v_lines) = tb_v6857; }
