    { const char * tb_v6865 = "    if (tb_memchk()) { tb_mem_touch((uintptr_t)src, (uint64_t)n, line); tb_mem_touch((uintptr_t)dst, (uint64_t)n, line); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6865; }
