    { const char * tb_v6869 = "// настоящее имя функции C (на Mac у имён в библиотеке спереди _)\n"; *(const char * *)tb_grow(v_lines) = tb_v6869; }
    { const char * tb_v6870 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v6870; }
    { const char * tb_v6871 = "#define TB_CSYM(s) __asm__(\"_\" s)\n"; *(const char * *)tb_grow(v_lines) = tb_v6871; }
    { const char * tb_v6872 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v6872; }
