    { const char * tb_v6874 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6874; }
    { const char * tb_v6875 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v6875; }
    { const char * tb_v6876 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6876; }
    { const char * tb_v6877 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v6877; }
    { const char * tb_v6878 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v6878; }
