    { const char * tb_v6882 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6882; }
    { const char * tb_v6883 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6883; }
    { const char * tb_v6884 = "// ---------- zone: область памяти. Много кусков берутся быстро и освобождаются разом ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6884; }
    { const char * tb_v6885 = "// Зона — цепочка больших кусков. zone_take отрезает от текущего куска (16 байт выравнивание, нули),\n"; *(const char * *)tb_grow(v_lines) = tb_v6885; }
    { const char * tb_v6886 = "// кончился кусок — берёт новый. zone_clear отдаёт всё, кроме первого куска; zone_free — всё.\n"; *(const char * *)tb_grow(v_lines) = tb_v6886; }
    { const char * tb_v6887 = "#define TB_ZONE_LIVE 0x5A4F4E454C495645ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v6887; }
    { const char * tb_v6888 = "typedef struct tb_zchunk { struct tb_zchunk *next; uint64_t size, used, pad; } tb_zchunk;   // 32 байта: данные с выравниванием 16\n"; *(const char * *)tb_grow(v_lines) = tb_v6888; }
    { const char * tb_v6889 = "typedef struct { uint64_t magic, step; tb_zchunk *first, *cur; } tb_zone;\n"; *(const char * *)tb_grow(v_lines) = tb_v6889; }
    { const char * tb_v6890 = "// данные куска: сразу за заголовком, с выравниванием 16 (malloc в ядре выравнивает меньше)\n"; *(const char * *)tb_grow(v_lines) = tb_v6890; }
    { const char * tb_v6891 = "#define TB_ZDATA(k) ((unsigned char *)(((uintptr_t)((k) + 1) + 15) & ~(uintptr_t)15))\n"; *(const char * *)tb_grow(v_lines) = tb_v6891; }
    { const char * tb_v6892 = "static tb_zchunk *tb_zone_chunk(uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6892; }
    { const char * tb_v6893 = "    tb_zchunk *k = malloc(sizeof(tb_zchunk) + (size_t)n + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v6893; }
    { const char * tb_v6894 = "    if (!k) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6894; }
    { const char * tb_v6895 = "    k->next = 0; k->size = n; k->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6895; }
    { const char * tb_v6896 = "    memset(TB_ZDATA(k), 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6896; }
    { const char * tb_v6897 = "    return k;\n"; *(const char * *)tb_grow(v_lines) = tb_v6897; }
    { const char * tb_v6898 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6898; }
    { const char * tb_v6899 = "// zone_new(байт): первый кусок такого размера; дальше куски того же размера (или больше, если нужно)\n"; *(const char * *)tb_grow(v_lines) = tb_v6899; }
