    { const char * tb_v7389 = "// короткий щелчок (касание тачпада): нажали и отпустили между двумя кадрами — mouse_down() всё равно разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v7389; }
    { const char * tb_v7390 = "TB_API int tb_mtap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7390; }
    { const char * tb_v7391 = "// колёсико: шагов с прошлого mouse_wheel() (+ вперёд, от себя; − назад); у тачпада шаги дробные — копим\n"; *(const char * *)tb_grow(v_lines) = tb_v7391; }
    { const char * tb_v7392 = "TB_API int tb_wheel = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7392; }
    { const char * tb_v7393 = "// боковые кнопки мыши: [0] назад, [1] вперёд; tap — нажали и отпустили между кадрами\n"; *(const char * *)tb_grow(v_lines) = tb_v7393; }
    { const char * tb_v7394 = "TB_API int tb_mside[2], tb_mside_tap[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7394; }
    { const char * tb_v7395 = "TB_API void tb_side(int b, int down) { tb_mside[b] = down; if (down) tb_mside_tap[b] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7395; }
    { const char * tb_v7396 = "TB_API double tb_wheel_f = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7396; }
    { const char * tb_v7397 = "TB_API void tb_wheel_add(double d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7397; }
    { const char * tb_v7398 = "    tb_wheel_f += d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7398; }
    { const char * tb_v7399 = "    int n = (int)tb_wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v7399; }
    { const char * tb_v7400 = "    tb_wheel += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7400; }
    { const char * tb_v7401 = "    tb_wheel_f -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7401; }
    { const char * tb_v7402 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7402; }
    { const char * tb_v7403 = "// буквы, набранные с прошлого typed_text(), в UTF-8 (стрелки, Enter и прочие не буквы не попадают)\n"; *(const char * *)tb_grow(v_lines) = tb_v7403; }
    { const char * tb_v7404 = "TB_API char tb_typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v7404; }
    { const char * tb_v7405 = "TB_API int tb_ntyped = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7405; }
