    { const char * tb_v8176 = "// ---------- шрифты TTF: свой чтец (таблицы glyf, без чужих библиотек) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v8176; }
    { const char * tb_v8177 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v8177; }
    { const char * tb_v8178 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v8178; }
    { const char * tb_v8179 = "typedef struct { unsigned char *d; size_t n; uint32_t glyf, loca, hmtx, cmap; int upem, locfmt, nglyphs, nhm, asc, desc, cfmt; } tb_font_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8179; }
    { const char * tb_v8180 = "TB_API tb_font_t *tb_fonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8180; }
    { const char * tb_v8181 = "TB_API int tb_nfonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8181; }
    { const char * tb_v8182 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8182; }
    { const char * tb_v8183 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8183; }
    { const char * tb_v8184 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8184; }
    { const char * tb_v8185 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8185; }
    { const char * tb_v8186 = "    unsigned n = tb_u16(f, base + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8186; }
    { const char * tb_v8187 = "    for (unsigned i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8187; }
    { const char * tb_v8188 = "        size_t e = base + 12 + 16 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v8188; }
    { const char * tb_v8189 = "        if (e + 16 <= f->n && memcmp(f->d + e, tag, 4) == 0) return tb_u32(f, e + 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v8189; }
    { const char * tb_v8190 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8190; }
    { const char * tb_v8191 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8191; }
    { const char * tb_v8192 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8192; }
    { const char * tb_v8193 = "TB_API void tb_gpu_blend_probe(void);   // TB_GPU_CHECK: проба смешивания букв (ниже)\n"; *(const char * *)tb_grow(v_lines) = tb_v8193; }
    { const char * tb_v8194 = "TB_API long long tb_load_font(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8194; }
    { const char * tb_v8195 = "    FILE *fp = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8195; }
    { const char * tb_v8196 = "    if (!fp) { tb_err = tb_cat(\"нет такого файла шрифта: \", path); return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8196; }
    { const char * tb_v8197 = "    fseek(fp, 0, SEEK_END); long sz = ftell(fp); fseek(fp, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v8197; }
    { const char * tb_v8198 = "    unsigned char *d = sz > 12 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8198; }
    { const char * tb_v8199 = "    if (!d || fread(d, 1, (size_t)sz, fp) != (size_t)sz) { fclose(fp); free(d); tb_err = \"не могу прочитать файл шрифта\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8199; }
    { const char * tb_v8200 = "    fclose(fp);\n"; *(const char * *)tb_grow(v_lines) = tb_v8200; }
    { const char * tb_v8201 = "    tb_font_t f = { d, (size_t)sz };\n"; *(const char * *)tb_grow(v_lines) = tb_v8201; }
    { const char * tb_v8202 = "    size_t base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8202; }
    { const char * tb_v8203 = "    if (memcmp(d, \"ttcf\", 4) == 0) base = tb_u32(&f, 12);   // сборник шрифтов (.ttc): берём первый\n"; *(const char * *)tb_grow(v_lines) = tb_v8203; }
    { const char * tb_v8204 = "    uint32_t head = tb_ttf_table(&f, base, \"head\"), maxp = tb_ttf_table(&f, base, \"maxp\"), hhea = tb_ttf_table(&f, base, \"hhea\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8204; }
    { const char * tb_v8205 = "    f.glyf = tb_ttf_table(&f, base, \"glyf\"); f.loca = tb_ttf_table(&f, base, \"loca\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8205; }
    { const char * tb_v8206 = "    f.hmtx = tb_ttf_table(&f, base, \"hmtx\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8206; }
    { const char * tb_v8207 = "    uint32_t cmap = tb_ttf_table(&f, base, \"cmap\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8207; }
    { const char * tb_v8208 = "    if (!f.glyf || !f.loca) { free(d); tb_err = \"этот шрифт не TrueType (контуры CFF/OTF пока не читаю): возьми .ttf\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8208; }
    { const char * tb_v8209 = "    if (!head || !maxp || !hhea || !f.hmtx || !cmap) { free(d); tb_err = \"шрифт сломан: нет нужных таблиц\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8209; }
    { const char * tb_v8210 = "    f.upem = (int)tb_u16(&f, head + 18); f.locfmt = tb_s16(&f, head + 50);\n"; *(const char * *)tb_grow(v_lines) = tb_v8210; }
    { const char * tb_v8211 = "    f.nglyphs = (int)tb_u16(&f, maxp + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8211; }
    { const char * tb_v8212 = "    f.asc = tb_s16(&f, hhea + 4); f.desc = tb_s16(&f, hhea + 6); f.nhm = (int)tb_u16(&f, hhea + 34);\n"; *(const char * *)tb_grow(v_lines) = tb_v8212; }
    { const char * tb_v8213 = "    if (f.upem <= 0 || f.nhm <= 0 || f.asc - f.desc <= 0) { free(d); tb_err = \"шрифт сломан: размеры\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8213; }
    { const char * tb_v8214 = "    // буквы → номера глифов: Unicode-таблица формата 12 (все буквы) или 4 (до U+FFFF)\n"; *(const char * *)tb_grow(v_lines) = tb_v8214; }
    { const char * tb_v8215 = "    unsigned nt = tb_u16(&f, cmap + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v8215; }
    { const char * tb_v8216 = "    int best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8216; }
    { const char * tb_v8217 = "    for (unsigned i = 0; i < nt; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8217; }
    { const char * tb_v8218 = "        size_t e = cmap + 4 + 8 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v8218; }
    { const char * tb_v8219 = "        unsigned pid = tb_u16(&f, e), eid = tb_u16(&f, e + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v8219; }
    { const char * tb_v8220 = "        uint32_t off = cmap + tb_u32(&f, e + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8220; }
    { const char * tb_v8221 = "        unsigned fmt = tb_u16(&f, off);\n"; *(const char * *)tb_grow(v_lines) = tb_v8221; }
    { const char * tb_v8222 = "        int score = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8222; }
    { const char * tb_v8223 = "        if (fmt == 12 && (pid == 0 || (pid == 3 && eid == 10))) score = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v8223; }
    { const char * tb_v8224 = "        else if (fmt == 4 && (pid == 0 || (pid == 3 && eid == 1))) score = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8224; }
    { const char * tb_v8225 = "        if (score > best) { best = score; f.cmap = off; f.cfmt = (int)fmt; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8225; }
    { const char * tb_v8226 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8226; }
    { const char * tb_v8227 = "    if (!best) { free(d); tb_err = \"в шрифте нет таблицы букв Unicode\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8227; }
    { const char * tb_v8228 = "    tb_font_t *all = realloc(tb_fonts, (size_t)(tb_nfonts + 1) * sizeof(tb_font_t));\n"; *(const char * *)tb_grow(v_lines) = tb_v8228; }
    { const char * tb_v8229 = "    if (!all) { free(d); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8229; }
    { const char * tb_v8230 = "    tb_fonts = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v8230; }
    { const char * tb_v8231 = "    tb_fonts[tb_nfonts++] = f;\n"; *(const char * *)tb_grow(v_lines) = tb_v8231; }
    { const char * tb_v8232 = "    tb_gpu_blend_probe();\n"; *(const char * *)tb_grow(v_lines) = tb_v8232; }
    { const char * tb_v8233 = "    return tb_nfonts - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8233; }
    { const char * tb_v8234 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8234; }
    { const char * tb_v8235 = "static unsigned tb_ttf_glyph(const tb_font_t *f, unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8235; }
    { const char * tb_v8236 = "    size_t c = f->cmap;\n"; *(const char * *)tb_grow(v_lines) = tb_v8236; }
    { const char * tb_v8237 = "    if (f->cfmt == 12) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8237; }
    { const char * tb_v8238 = "        uint32_t n = tb_u32(f, c + 12);\n"; *(const char * *)tb_grow(v_lines) = tb_v8238; }
    { const char * tb_v8239 = "        for (uint32_t lo = 0, hi = n; lo < hi;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8239; }
    { const char * tb_v8240 = "            uint32_t mid = (lo + hi) / 2; size_t g = c + 16 + 12 * (size_t)mid;\n"; *(const char * *)tb_grow(v_lines) = tb_v8240; }
    { const char * tb_v8241 = "            uint32_t a = tb_u32(f, g), b = tb_u32(f, g + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8241; }
    { const char * tb_v8242 = "            if (u < a) hi = mid; else if (u > b) lo = mid + 1; else return tb_u32(f, g + 8) + (u - a);\n"; *(const char * *)tb_grow(v_lines) = tb_v8242; }
    { const char * tb_v8243 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8243; }
    { const char * tb_v8244 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8244; }
    { const char * tb_v8245 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8245; }
    { const char * tb_v8246 = "    if (u > 0xFFFF) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8246; }
    { const char * tb_v8247 = "    unsigned segs = tb_u16(f, c + 6) / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8247; }
    { const char * tb_v8248 = "    size_t ends = c + 14, starts = ends + 2 * segs + 2, deltas = starts + 2 * segs, ranges = deltas + 2 * segs;\n"; *(const char * *)tb_grow(v_lines) = tb_v8248; }
    { const char * tb_v8249 = "    for (unsigned i = 0; i < segs; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8249; }
    { const char * tb_v8250 = "        if (u > tb_u16(f, ends + 2 * i)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8250; }
    { const char * tb_v8251 = "        unsigned s = tb_u16(f, starts + 2 * i);\n"; *(const char * *)tb_grow(v_lines) = tb_v8251; }
    { const char * tb_v8252 = "        if (u < s) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8252; }
    { const char * tb_v8253 = "        unsigned delta = tb_u16(f, deltas + 2 * i), ro = tb_u16(f, ranges + 2 * i);\n"; *(const char * *)tb_grow(v_lines) = tb_v8253; }
    { const char * tb_v8254 = "        if (ro == 0) return (u + delta) & 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8254; }
    { const char * tb_v8255 = "        unsigned g = tb_u16(f, ranges + 2 * i + ro + 2 * (u - s));\n"; *(const char * *)tb_grow(v_lines) = tb_v8255; }
    { const char * tb_v8256 = "        return g ? (g + delta) & 0xFFFF : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8256; }
    { const char * tb_v8257 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8257; }
    { const char * tb_v8258 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8258; }
    { const char * tb_v8259 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8259; }
    { const char * tb_v8260 = "static double tb_ttf_adv(const tb_font_t *f, unsigned g) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8260; }
    { const char * tb_v8261 = "    unsigned i = (int)g < f->nhm ? g : (unsigned)f->nhm - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8261; }
    { const char * tb_v8262 = "    return tb_u16(f, f->hmtx + 4 * (size_t)i);\n"; *(const char * *)tb_grow(v_lines) = tb_v8262; }
    { const char * tb_v8263 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8263; }
    { const char * tb_v8264 = "static size_t tb_ttf_gpos(const tb_font_t *f, unsigned g, size_t *len) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8264; }
    { const char * tb_v8265 = "    if ((int)g >= f->nglyphs) { *len = 0; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8265; }
    { const char * tb_v8266 = "    size_t a, b;\n"; *(const char * *)tb_grow(v_lines) = tb_v8266; }
    { const char * tb_v8267 = "    if (f->locfmt == 0) { a = 2 * (size_t)tb_u16(f, f->loca + 2 * g); b = 2 * (size_t)tb_u16(f, f->loca + 2 * g + 2); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8267; }
    { const char * tb_v8268 = "    else { a = tb_u32(f, f->loca + 4 * g); b = tb_u32(f, f->loca + 4 * g + 4); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8268; }
    { const char * tb_v8269 = "    *len = b > a ? b - a : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8269; }
    { const char * tb_v8270 = "    return f->glyf + a;\n"; *(const char * *)tb_grow(v_lines) = tb_v8270; }
    { const char * tb_v8271 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8271; }
    { const char * tb_v8272 = "// контур буквы → отрезки (в точках экрана, y вниз); m — матрица шрифт → экран: x' = m0 x + m2 y + m4, y' = m1 x + m3 y + m5\n"; *(const char * *)tb_grow(v_lines) = tb_v8272; }
    { const char * tb_v8273 = "typedef struct { float *e; int n, cap; } tb_edges;\n"; *(const char * *)tb_grow(v_lines) = tb_v8273; }
    { const char * tb_v8274 = "static void tb_edge(tb_edges *E, double x0, double y0, double x1, double y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8274; }
    { const char * tb_v8275 = "    if (y0 == y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8275; }
    { const char * tb_v8276 = "    if (E->n == E->cap) { E->cap = E->cap ? E->cap * 2 : 256; E->e = realloc(E->e, (size_t)E->cap * 4 * sizeof(float)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8276; }
    { const char * tb_v8277 = "    float *p = E->e + 4 * E->n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8277; }
    { const char * tb_v8278 = "    p[0] = (float)x0; p[1] = (float)y0; p[2] = (float)x1; p[3] = (float)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8278; }
    { const char * tb_v8279 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8279; }
    { const char * tb_v8280 = "static void tb_quad(tb_edges *E, double x0, double y0, double cx, double cy, double x1, double y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8280; }
    { const char * tb_v8281 = "    double dx = x0 - 2 * cx + x1, dy = y0 - 2 * cy + y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8281; }
    { const char * tb_v8282 = "    int n = 1 + (int)sqrt(sqrt(dx * dx + dy * dy) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8282; }
    { const char * tb_v8283 = "    if (n > 16) n = 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v8283; }
    { const char * tb_v8284 = "    double px = x0, py = y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8284; }
    { const char * tb_v8285 = "    for (int i = 1; i <= n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8285; }
    { const char * tb_v8286 = "        double t = (double)i / n, u = 1 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8286; }
    { const char * tb_v8287 = "        double qx = u * u * x0 + 2 * u * t * cx + t * t * x1, qy = u * u * y0 + 2 * u * t * cy + t * t * y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8287; }
    { const char * tb_v8288 = "        tb_edge(E, px, py, qx, qy);\n"; *(const char * *)tb_grow(v_lines) = tb_v8288; }
    { const char * tb_v8289 = "        px = qx; py = qy;\n"; *(const char * *)tb_grow(v_lines) = tb_v8289; }
    { const char * tb_v8290 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8290; }
    { const char * tb_v8291 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8291; }
    { const char * tb_v8292 = "static void tb_ttf_outline(const tb_font_t *f, unsigned g, const double *m, tb_edges *E, int depth) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8292; }
    { const char * tb_v8293 = "    size_t len, o = tb_ttf_gpos(f, g, &len);\n"; *(const char * *)tb_grow(v_lines) = tb_v8293; }
    { const char * tb_v8294 = "    if (len < 10 || depth > 8) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8294; }
    { const char * tb_v8295 = "    int nc = tb_s16(f, o);\n"; *(const char * *)tb_grow(v_lines) = tb_v8295; }
    { const char * tb_v8296 = "    if (nc < 0) {   // составная буква (ё = е + точки): части со своим сдвигом и масштабом\n"; *(const char * *)tb_grow(v_lines) = tb_v8296; }
    { const char * tb_v8297 = "        size_t p = o + 10;\n"; *(const char * *)tb_grow(v_lines) = tb_v8297; }
    { const char * tb_v8298 = "        for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8298; }
    { const char * tb_v8299 = "            unsigned fl = tb_u16(f, p), sub = tb_u16(f, p + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v8299; }
    { const char * tb_v8300 = "            p += 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v8300; }
    { const char * tb_v8301 = "            double dx = 0, dy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8301; }
    { const char * tb_v8302 = "            if (fl & 1) { if (fl & 2) { dx = tb_s16(f, p); dy = tb_s16(f, p + 2); } p += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8302; }
    { const char * tb_v8303 = "            else { if (fl & 2) { dx = (int8_t)f->d[p]; dy = (int8_t)f->d[p + 1]; } p += 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8303; }
    { const char * tb_v8304 = "            double a = 1, b = 0, c = 0, dd = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8304; }
