    { const char * tb_v8450 = "    int left = (int)floor(tb_s16(f, o + 2) * s) - 1, right = (int)ceil(tb_s16(f, o + 6) * s) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8450; }
    { const char * tb_v8451 = "    int top = (int)floor(-tb_s16(f, o + 8) * s) - 1, bottom = (int)ceil(-tb_s16(f, o + 4) * s) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8451; }
