    { const char * tb_v8478 = "    tb_imgs[tb_nimg].w = w; tb_imgs[tb_nimg].h = h; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8478; }
    { const char * tb_v8479 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v8479; }
