    { const char * tb_v8484 = "// высота строки — size * 5 / 4; линия букв — так, чтобы верх и низ шрифта легли в эту строку\n"; *(const char * *)tb_grow(v_lines) = tb_v8484; }
    { const char * tb_v8485 = "static int tb_font_base(const tb_font_t *f, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8485; }
    { const char * tb_v8486 = "    double lh = size * 5 / 4.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8486; }
    { const char * tb_v8487 = "    return (int)floor(lh * f->asc / (f->asc - f->desc) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8487; }
    { const char * tb_v8488 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8488; }
    { const char * tb_v8489 = "static unsigned tb_utf8_next(const unsigned char **pp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8489; }
    { const char * tb_v8490 = "    const unsigned char *p = *pp;\n"; *(const char * *)tb_grow(v_lines) = tb_v8490; }
    { const char * tb_v8491 = "    unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8491; }
    { const char * tb_v8492 = "    if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8492; }
    { const char * tb_v8493 = "        int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8493; }
    { const char * tb_v8494 = "        u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v8494; }
    { const char * tb_v8495 = "        while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v8495; }
    { const char * tb_v8496 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8496; }
    { const char * tb_v8497 = "    *pp = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v8497; }
    { const char * tb_v8498 = "    return u;\n"; *(const char * *)tb_grow(v_lines) = tb_v8498; }
    { const char * tb_v8499 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8499; }
    { const char * tb_v8500 = "TB_API long long tb_text_width(long long fi, const char *s, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8500; }
    { const char * tb_v8501 = "    if (fi < 0 || fi >= tb_nfonts || size <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8501; }
    { const char * tb_v8502 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v8502; }
    { const char * tb_v8503 = "    double scale = (double)size / f->upem, pen = 0, best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8503; }
    { const char * tb_v8504 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v8504; }
    { const char * tb_v8505 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8505; }
    { const char * tb_v8506 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v8506; }
    { const char * tb_v8507 = "        if (u == '\\n') { if (pen > best) best = pen; pen = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8507; }
    { const char * tb_v8508 = "        pen += tb_ttf_adv(f, tb_ttf_glyph(f, u)) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v8508; }
    { const char * tb_v8509 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8509; }
    { const char * tb_v8510 = "    if (pen > best) best = pen;\n"; *(const char * *)tb_grow(v_lines) = tb_v8510; }
    { const char * tb_v8511 = "    return (long long)floor(best + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8511; }
    { const char * tb_v8512 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8512; }
    { const char * tb_v8513 = "TB_API void tb_draw_image_a(long long id, long long x, long long y);\n"; *(const char * *)tb_grow(v_lines) = tb_v8513; }
    { const char * tb_v8514 = "TB_API void tb_draw_font(long long fi, long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8514; }
    { const char * tb_v8515 = "    if (!tb_px || fi < 0 || fi >= tb_nfonts || size <= 0 || size > 1000) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8515; }
    { const char * tb_v8516 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v8516; }
    { const char * tb_v8517 = "    double scale = (double)size / f->upem, pen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8517; }
    { const char * tb_v8518 = "    long long base = y + tb_font_base(f, size), lh = size * 5 / 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v8518; }
