    { const char * tb_v8520 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8520; }
    { const char * tb_v8521 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v8521; }
