    { const char * tb_v8531 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v8531; }
    { const char * tb_v8532 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v8532; }
    { const char * tb_v8533 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v8533; }
    { const char * tb_v8534 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v8534; }
    { const char * tb_v8535 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v8535; }
    { const char * tb_v8536 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v8536; }
    { const char * tb_v8537 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v8537; }
    { const char * tb_v8538 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v8538; }
    { const char * tb_v8539 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v8539; }
    { const char * tb_v8540 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8540; }
    { const char * tb_v8541 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8541; }
    { const char * tb_v8542 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v8542; }
    { const char * tb_v8543 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8543; }
    { const char * tb_v8544 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v8544; }
    { const char * tb_v8545 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v8545; }
    { const char * tb_v8546 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8546; }
    { const char * tb_v8547 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8547; }
    { const char * tb_v8548 = "// 3D с картинкой (mesh_image): у треугольника ещё запись текстуры — плоскости u·W и v·W (по 64 бита)\n"; *(const char * *)tb_grow(v_lines) = tb_v8548; }
    { const char * tb_v8549 = "// и сама картинка; номер записи — в pad его плоскости глубины, а в m ещё бит 29\n"; *(const char * *)tb_grow(v_lines) = tb_v8549; }
    { const char * tb_v8550 = "typedef struct { int64_t au, bu, cu, av, bv, cv; uint32_t off, w, h, pad; } tb_gtex_t;   // 64 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v8550; }
    { const char * tb_v8551 = "enum { TB_GT_CAP = 16384 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8551; }
    { const char * tb_v8552 = "TB_API tb_gtex_t *tb_gtex = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8552; }
    { const char * tb_v8553 = "TB_API int tb_gtn = 0, tb_gpu_tex = 0;   // записей в текущем наборе; видеокарта умеет картинки на сетках\n"; *(const char * *)tb_grow(v_lines) = tb_v8553; }
    { const char * tb_v8554 = "// «новые» треугольники 3D (свет по углам, тени, туман, прозрачность — см. tb_lit_px): у каждого запись — W трёх углов,\n"; *(const char * *)tb_grow(v_lines) = tb_v8554; }
    { const char * tb_v8555 = "// флаги (1 — тени, 2 — туман, прозрачность << 8), по 12 чисел на угол (значение × W), туман, картинка, карта теней.\n"; *(const char * *)tb_grow(v_lines) = tb_v8555; }
    { const char * tb_v8556 = "// Номер записи — в pad плоскости глубины, а в m — бит 28 (и бит 27 у прозрачного)\n"; *(const char * *)tb_grow(v_lines) = tb_v8556; }
    { const char * tb_v8557 = "typedef struct { int32_t w[3], flags; int32_t v[3][12]; int32_t fogc, fogn, fogf, tex, smn, smbase, pad0, pad1; } tb_glit_t;   // 192 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v8557; }
    { const char * tb_v8558 = "enum { TB_GL_CAP = 16384, TB_LV = 11, TB_SM_N = 1024 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8558; }
    { const char * tb_v8559 = "TB_API tb_glit_t *tb_glit = 0;           // записи всех наборов (видны видеокарте; появляются при первом таком треугольнике)\n"; *(const char * *)tb_grow(v_lines) = tb_v8559; }
    { const char * tb_v8560 = "TB_API int tb_gln = 0, tb_gpu_lit = 0;   // записей в текущем наборе; видеокарта умеет такие треугольники\n"; *(const char * *)tb_grow(v_lines) = tb_v8560; }
    { const char * tb_v8561 = "TB_API void tb_gpu_lit_mem(int shadow);  // своя у каждой системы: память записей (0) или карт теней (1)\n"; *(const char * *)tb_grow(v_lines) = tb_v8561; }
    { const char * tb_v8562 = "TB_API void tb_gpu_tril(const long long *t, long long c, const uint32_t *pl, const tb_glit_t *L, const tb_gtex_t *tx);\n"; *(const char * *)tb_grow(v_lines) = tb_v8562; }
    { const char * tb_v8563 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v8563; }
    { const char * tb_v8564 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v8564; }
    { const char * tb_v8565 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v8565; }
    { const char * tb_v8566 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8566; }
    { const char * tb_v8567 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v8567; }
    { const char * tb_v8568 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v8568; }
    { const char * tb_v8569 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v8569; }
    { const char * tb_v8570 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v8570; }
    { const char * tb_v8571 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v8571; }
    { const char * tb_v8572 = "typedef struct { int32_t r[16]; } tb_grec;   // 4 строки: поворот × 2^30 и сдвиг × 4096 (3), свет в сетке (x, y, z × 2^14, фон × 256; фон -1 — без света)\n"; *(const char * *)tb_grow(v_lines) = tb_v8572; }
    { const char * tb_v8573 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8573; }
    { const char * tb_v8574 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v8574; }
    { const char * tb_v8575 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v8575; }
    { const char * tb_v8576 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v8576; }
