    { const char * tb_v8602 = "TB_API int tb_mlock = 0, tb_mseen = 0, tb_mwarp = 0, tb_cursor_prog = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8602; }
    { const char * tb_v8603 = "TB_API void tb_gfx_fullscreen(int on);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v8603; }
    { const char * tb_v8604 = "TB_API void tb_gfx_lock(int on);\n"; *(const char * *)tb_grow(v_lines) = tb_v8604; }
    { const char * tb_v8605 = "// мышь в точке (x, y) окна: копим сдвиг. Захвачена — меряем от середины окна, мышь потом вернётся туда\n"; *(const char * *)tb_grow(v_lines) = tb_v8605; }
    { const char * tb_v8606 = "TB_API void tb_mouse_at(int x, int y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8606; }
    { const char * tb_v8607 = "    if (tb_mlock) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8607; }
    { const char * tb_v8608 = "        int cx = tb_gw / 2, cy = tb_gh / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8608; }
    { const char * tb_v8609 = "        if (x == cx && y == cy) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8609; }
    { const char * tb_v8610 = "        tb_mdx += x - cx; tb_mdy += y - cy; tb_mwarp = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8610; }
    { const char * tb_v8611 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8611; }
    { const char * tb_v8612 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8612; }
    { const char * tb_v8613 = "    if (tb_mseen) { tb_mdx += x - tb_mx; tb_mdy += y - tb_my; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8613; }
    { const char * tb_v8614 = "    tb_mseen = 1; tb_mx = x; tb_my = y;\n"; *(const char * *)tb_grow(v_lines) = tb_v8614; }
    { const char * tb_v8615 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8615; }
    { const char * tb_v8616 = "TB_API int tb_sharp = 0;       // window_sharp(): окно в настоящих точках экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v8616; }
    { const char * tb_v8617 = "TB_API double tb_sc = 1;        // во сколько раз точек больше (Retina — 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v8617; }
    { const char * tb_v8618 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v8618; }
    { const char * tb_v8619 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v8619; }
    { const char * tb_v8620 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8620; }
    { const char * tb_v8621 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8621; }
    { const char * tb_v8622 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v8622; }
    { const char * tb_v8623 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8623; }
    { const char * tb_v8624 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v8624; }
    { const char * tb_v8625 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8625; }
    { const char * tb_v8626 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8626; }
    { const char * tb_v8627 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8627; }
    { const char * tb_v8628 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, tb_tr(\"окно: рисует %s\\n\"), what);\n"; *(const char * *)tb_grow(v_lines) = tb_v8628; }
    { const char * tb_v8629 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8629; }
    { const char * tb_v8630 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8630; }
    { const char * tb_v8631 = "    fprintf(stderr, tb_tr(\"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\"), tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v8631; }
    { const char * tb_v8632 = "    if (tb_gpu_shskip) fprintf(stderr, tb_tr(\"TB_GPU_CHECK: кадров со своими шейдерами (не сверялись): %lld\\n\"), tb_gpu_shskip);\n"; *(const char * *)tb_grow(v_lines) = tb_v8632; }
    { const char * tb_v8633 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8633; }
    { const char * tb_v8634 = "// ---- gpu func (1.3): шейдеры программы — их собрал компилятор Tachbit из gpu func ----\n"; *(const char * *)tb_grow(v_lines) = tb_v8634; }
    { const char * tb_v8635 = "// У каждого: имя, вид (0 — углы, 1 — точка), функция для процессора, SPIR-V, имена настроек по порядку.\n"; *(const char * *)tb_grow(v_lines) = tb_v8635; }
    { const char * tb_v8636 = "// Metal берёт все шейдеры из одного текста tb_sh_msl. Сетка со своим шейдером рисуется обычными\n"; *(const char * *)tb_grow(v_lines) = tb_v8636; }
    { const char * tb_v8637 = "// дробными числами (не точка в точку с процессором): в пачке это фигура m = 7 — x0 номер записи,\n"; *(const char * *)tb_grow(v_lines) = tb_v8637; }
    { const char * tb_v8638 = "// y0 шейдер углов, x1 шейдер точки, y1 сколько углов; углы сетки лежат в своём буфере видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v8638; }
    { const char * tb_v8639 = "// R — своя запись draw_mesh (лампы, картинки, тени), T — точки всех картинок (tb_imgpx), S — карты теней (tb_shm)\n"; *(const char * *)tb_grow(v_lines) = tb_v8639; }
    { const char * tb_v8640 = "typedef void (*tb_shfn)(const float *R, const uint32_t *T, const uint32_t *S, float *io);\n"; *(const char * *)tb_grow(v_lines) = tb_v8640; }
    { const char * tb_v8641 = "// Вид 2 — шейдер экрана (screen_shader): функция (io, кадр, глубина), в пачке фигура m = 8 — x0 номер записи, x1 шейдер;\n"; *(const char * *)tb_grow(v_lines) = tb_v8641; }
    { const char * tb_v8642 = "// вид 3 — вершины для экрана (один треугольник на всё окно). sv — настройки шейдера экрана (screen_set)\n"; *(const char * *)tb_grow(v_lines) = tb_v8642; }
    { const char * tb_v8643 = "typedef void (*tb_scrfn)(const float *R, const uint32_t *T, const uint32_t *S, float *io, const uint32_t *scr, const float *scz);\n"; *(const char * *)tb_grow(v_lines) = tb_v8643; }
    { const char * tb_v8644 = "typedef struct { const char *name; int stage; tb_shfn fn; const uint32_t *spv; size_t bytes; int nsets; char sets[8][32]; float sv[8]; } tb_shader_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8644; }
    { const char * tb_v8645 = "enum { TB_SH_MAX = 64, TB_SHR_CAP = 4096, TB_SHR_N = 224, TB_SHB_CAP = 12 * 32768 };   // TB_SHB_CAP — числа матриц костей на набор\n"; *(const char * *)tb_grow(v_lines) = tb_v8645; }
    { const char * tb_v8646 = "TB_API tb_shader_t tb_shaders[TB_SH_MAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v8646; }
    { const char * tb_v8647 = "TB_API int tb_nshaders = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8647; }
    { const char * tb_v8648 = "TB_API const char *tb_sh_msl = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8648; }
    { const char * tb_v8649 = "TB_API float *tb_shrecs = 0;          // записи текущего набора: TB_SHR_N чисел на draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v8649; }
    { const char * tb_v8650 = "TB_API int tb_shrn = 0;            // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v8650; }
    { const char * tb_v8651 = "TB_API float *tb_shbones = 0;      // матрицы костей текущего набора (после всех записей в том же буфере)\n"; *(const char * *)tb_grow(v_lines) = tb_v8651; }
    { const char * tb_v8652 = "TB_API long long tb_shbn = 0, tb_shbase = 0;   // сколько чисел занято; где они начинаются в буфере (номер числа)\n"; *(const char * *)tb_grow(v_lines) = tb_v8652; }
    { const char * tb_v8653 = "#define TB_SHB_AT(map) do { tb_shbase = (long long)TB_SHR_N * TB_SHR_CAP * TB_GSLOTS + (long long)tb_gslot * TB_SHB_CAP; tb_shbones = (map) + tb_shbase; tb_shbn = 0; } while (0)\n"; *(const char * *)tb_grow(v_lines) = tb_v8653; }
    { const char * tb_v8654 = "TB_API int tb_sh_frame = 0;        // в кадре была сетка со своим шейдером: TB_GPU_CHECK кадр не сверяет\n"; *(const char * *)tb_grow(v_lines) = tb_v8654; }
    { const char * tb_v8655 = "TB_API void tb_sh_lib(const char *msl) { tb_sh_msl = msl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8655; }
    { const char * tb_v8656 = "TB_API void tb_sh_reg(const char *name, int stage, tb_shfn fn, const uint32_t *spv, size_t bytes, const char *sets) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8656; }
    { const char * tb_v8657 = "    if (tb_nshaders == TB_SH_MAX) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8657; }
    { const char * tb_v8658 = "    tb_shader_t *s = &tb_shaders[tb_nshaders++];\n"; *(const char * *)tb_grow(v_lines) = tb_v8658; }
    { const char * tb_v8659 = "    memset(s, 0, sizeof *s);\n"; *(const char * *)tb_grow(v_lines) = tb_v8659; }
    { const char * tb_v8660 = "    s->name = name; s->stage = stage; s->fn = fn; s->spv = spv; s->bytes = bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v8660; }
    { const char * tb_v8661 = "    for (const char *p = sets; *p && s->nsets < 8;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8661; }
    { const char * tb_v8662 = "        int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8662; }
    { const char * tb_v8663 = "        while (p[n] && p[n] != ',') n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8663; }
    { const char * tb_v8664 = "        int k = n > 31 ? 31 : n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8664; }
    { const char * tb_v8665 = "        memcpy(s->sets[s->nsets], p, (size_t)k);\n"; *(const char * *)tb_grow(v_lines) = tb_v8665; }
    { const char * tb_v8666 = "        s->sets[s->nsets][k] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8666; }
    { const char * tb_v8667 = "        s->nsets++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8667; }
    { const char * tb_v8668 = "        p += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8668; }
    { const char * tb_v8669 = "        if (*p == ',') p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8669; }
    { const char * tb_v8670 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8670; }
    { const char * tb_v8671 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8671; }
    { const char * tb_v8672 = "TB_API int tb_sh_find(const char *name, int stage) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8672; }
    { const char * tb_v8673 = "    for (int i = 0; i < tb_nshaders; i++) if (tb_shaders[i].stage == stage && strcmp(tb_shaders[i].name, name) == 0) return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v8673; }
    { const char * tb_v8674 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8674; }
    { const char * tb_v8675 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8675; }
    { const char * tb_v8676 = "// свои у каждой системы: готова ли видеокарта; углы сетки в её буфер (старый отдаётся); фигура m = 7 в пачку\n"; *(const char * *)tb_grow(v_lines) = tb_v8676; }
    { const char * tb_v8677 = "TB_API int tb_gpu_sh_ready(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v8677; }
    { const char * tb_v8678 = "TB_API void *tb_gpu_sh_vbuf(void *old, const float *v, long long nfloats);\n"; *(const char * *)tb_grow(v_lines) = tb_v8678; }
    { const char * tb_v8679 = "TB_API void tb_gpu_sh_add(void *vb, int cs, int ps, long long nverts, int nowrite);   // nowrite: глубину не писать (прозрачная сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v8679; }
    { const char * tb_v8680 = "TB_API int tb_gpu_scr_ready(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v8680; }
    { const char * tb_v8681 = "// ---- тени для gpu func: карта солнца (1024 × 1024) и кубы ламп (6 × 256 × 256, до 4 ламп) по 16 бит —\n"; *(const char * *)tb_grow(v_lines) = tb_v8681; }
    { const char * tb_v8682 = "// две глубины в слове; у каждого набора видеокарты свои (прошлые кадры ещё рисуются). Начало — число 207 записи\n"; *(const char * *)tb_grow(v_lines) = tb_v8682; }
    { const char * tb_v8683 = "enum { TB_LSM_N = 256, TB_LSM_MAX = 4 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8683; }
    { const char * tb_v8684 = "#define TB_SHM_SLOT ((size_t)1024 * 1024 + (size_t)TB_LSM_MAX * 6 * TB_LSM_N * TB_LSM_N)\n"; *(const char * *)tb_grow(v_lines) = tb_v8684; }
    { const char * tb_v8685 = "TB_API uint32_t *tb_shm = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8685; }
    { const char * tb_v8686 = "TB_API int tb_lshadow[8];             // light_shadow: лампа даёт тени\n"; *(const char * *)tb_grow(v_lines) = tb_v8686; }
    { const char * tb_v8687 = "TB_API int tb_lsm_of[8] = { -1, -1, -1, -1, -1, -1, -1, -1 };   // куб лампы в картах этой сцены\n"; *(const char * *)tb_grow(v_lines) = tb_v8687; }
    { const char * tb_v8688 = "TB_API int tb_shm_sun = 0;            // в картах этой сцены есть солнце\n"; *(const char * *)tb_grow(v_lines) = tb_v8688; }
    { const char * tb_v8689 = "TB_API long long tb_shm_batch = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8689; }
    { const char * tb_v8690 = "TB_API uint32_t *tb_gpu_shm(void);    // своя у каждой системы: память карт, которую видит видеокарта (0 — нет)\n"; *(const char * *)tb_grow(v_lines) = tb_v8690; }
    { const char * tb_v8691 = "TB_API void tb_gpu_scr_add(int ps);\n"; *(const char * *)tb_grow(v_lines) = tb_v8691; }
    { const char * tb_v8692 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v8692; }
    { const char * tb_v8693 = "// TB_GPU_CHECK: как видеокарта смешивает букву с фоном — таблица из пробы (tb_gpu_blend_probe)\n"; *(const char * *)tb_grow(v_lines) = tb_v8693; }
    { const char * tb_v8694 = "TB_API int tb_blend_cal = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8694; }
