    { const char * tb_v8727 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8727; }
    { const char * tb_v8728 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8728; }
    { const char * tb_v8729 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8729; }
    { const char * tb_v8730 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8730; }
    { const char * tb_v8731 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8731; }
