    { const char * tb_v8737 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8737; }
    { const char * tb_v8738 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8738; }
    { const char * tb_v8739 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8739; }
    { const char * tb_v8740 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8740; }
    { const char * tb_v8741 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8741; }
    { const char * tb_v8742 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8742; }
    { const char * tb_v8743 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8743; }
    { const char * tb_v8744 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8744; }
    { const char * tb_v8745 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v8745; }
    { const char * tb_v8746 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v8746; }
    { const char * tb_v8747 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8747; }
    { const char * tb_v8748 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v8748; }
    { const char * tb_v8749 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v8749; }
