    { const char * tb_v8751 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8751; }
    { const char * tb_v8752 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8752; }
