    { const char * tb_v11796 = "TB_API void tb_ps2_wait_in(void) { for (int i = 0; i < 100000 && (tb_inb(0x64) & 2); i++) {} }\n"; *(const char * *)tb_grow(v_lines) = tb_v11796; }
    { const char * tb_v11797 = "TB_API int tb_ps2_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11797; }
    { const char * tb_v11798 = "    for (int i = 0; i < 100000; i++) if (tb_inb(0x64) & 1) return tb_inb(0x60);\n"; *(const char * *)tb_grow(v_lines) = tb_v11798; }
    { const char * tb_v11799 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11799; }
