    { const char * tb_v11805 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11805; }
    { const char * tb_v11806 = "// «мышь виртуальной машины» (vmmouse в QEMU и VMware): точное место курсора, а не сдвиги —\n"; *(const char * *)tb_grow(v_lines) = tb_v11806; }
    { const char * tb_v11807 = "// мышь не надо «ловить» в окне QEMU. Есть — берём её, нет — обычные пакеты PS/2\n"; *(const char * *)tb_grow(v_lines) = tb_v11807; }
    { const char * tb_v11808 = "TB_API int tb_vmm = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11808; }
    { const char * tb_v11809 = "TB_API void tb_vmm_call(uint32_t cmd, uint32_t arg, uint32_t r[4]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11809; }
    { const char * tb_v11810 = "    uint32_t a = 0x564D5868u, b = arg, c = cmd, d = 0x5658;\n"; *(const char * *)tb_grow(v_lines) = tb_v11810; }
    { const char * tb_v11811 = "    __asm__ volatile(\"inl %%dx, %%eax\" : \"+a\"(a), \"+b\"(b), \"+c\"(c), \"+d\"(d) : : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v11811; }
    { const char * tb_v11812 = "    r[0] = a; r[1] = b; r[2] = c; r[3] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v11812; }
    { const char * tb_v11813 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11813; }
    { const char * tb_v11814 = "TB_API void tb_vmm_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11814; }
