    { const char * tb_v11816 = "    tb_vmm_call(10, 0, r);                               // «кто здесь»: в ответе ebx — тот же магический номер\n"; *(const char * *)tb_grow(v_lines) = tb_v11816; }
    { const char * tb_v11817 = "    if (r[1] != 0x564D5868u) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11817; }
    { const char * tb_v11818 = "    tb_vmm_call(41, 0x45414552u, r);                     // включить\n"; *(const char * *)tb_grow(v_lines) = tb_v11818; }
    { const char * tb_v11819 = "    tb_vmm_call(40, 0, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v11819; }
    { const char * tb_v11820 = "    if (r[0] == 0xFFFF0000u || (r[0] & 0xFFFF) == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11820; }
    { const char * tb_v11821 = "    tb_vmm_call(39, 1, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v11821; }
    { const char * tb_v11822 = "    if (r[0] != 0x3442554Au) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11822; }
    { const char * tb_v11823 = "    tb_vmm_call(41, 0x53424152u, r);                     // точные координаты\n"; *(const char * *)tb_grow(v_lines) = tb_v11823; }
    { const char * tb_v11824 = "    tb_vmm = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11824; }
    { const char * tb_v11825 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11825; }
    { const char * tb_v11826 = "TB_API void tb_vmm_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11826; }
    { const char * tb_v11827 = "    uint32_t r[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v11827; }
    { const char * tb_v11828 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11828; }
    { const char * tb_v11829 = "        tb_vmm_call(40, 0, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v11829; }
    { const char * tb_v11830 = "        if (r[0] == 0xFFFF0000u) { tb_vmm = 0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11830; }
