    { const char * tb_v11841 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11841; }
    { const char * tb_v11842 = "TB_API void tb_mouse_irq(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11842; }
    { const char * tb_v11843 = "    unsigned char st = tb_inb(0x64);\n"; *(const char * *)tb_grow(v_lines) = tb_v11843; }
    { const char * tb_v11844 = "    if (!(st & 1)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11844; }
