    { const char * tb_v11853 = "    if (tb_mpk[0] & 0xC0) dx = dy = 0;            // переполнение: пакет не верен\n"; *(const char * *)tb_grow(v_lines) = tb_v11853; }
    { const char * tb_v11854 = "    tb_mx += dx; tb_my -= dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v11854; }
    { const char * tb_v11855 = "    if (tb_mx < 0) tb_mx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11855; }
    { const char * tb_v11856 = "    if (tb_my < 0) tb_my = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11856; }
    { const char * tb_v11857 = "    if (tb_mx >= tb_gw) tb_mx = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11857; }
    { const char * tb_v11858 = "    if (tb_my >= tb_gh) tb_my = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11858; }
    { const char * tb_v11859 = "    int down = tb_mpk[0] & 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11859; }
    { const char * tb_v11860 = "    if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11860; }
    { const char * tb_v11861 = "    tb_mdown = down;\n"; *(const char * *)tb_grow(v_lines) = tb_v11861; }
    { const char * tb_v11862 = "    if (tb_mpsize == 4) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11862; }
