    { const char * tb_v11879 = "    // колёсико: «волшебные» частоты 200, 100, 80, потом мышь называет себя 3\n"; *(const char * *)tb_grow(v_lines) = tb_v11879; }
    { const char * tb_v11880 = "    tb_mouse_cmd(0xF3); tb_mouse_cmd(200); tb_mouse_cmd(0xF3); tb_mouse_cmd(100); tb_mouse_cmd(0xF3); tb_mouse_cmd(80);\n"; *(const char * *)tb_grow(v_lines) = tb_v11880; }
    { const char * tb_v11881 = "    if (tb_mouse_cmd(0xF2) == 0xFA && tb_ps2_read() == 3) tb_mpsize = 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v11881; }
    { const char * tb_v11882 = "    tb_mouse_cmd(0xF4);                            // слать движения\n"; *(const char * *)tb_grow(v_lines) = tb_v11882; }
