    { const char * tb_v13176 = "// буфер обмена Windows: текст в UTF-16\n"; *(const char * *)tb_grow(v_lines) = tb_v13176; }
    { const char * tb_v13177 = "TB_API char *tb_gfx_clip_get(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13177; }
    { const char * tb_v13178 = "    if (!OpenClipboard(tb_hwnd)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13178; }
