    { const char * tb_v13477 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v13477; }
    { const char * tb_v13478 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v13478; }
    { const char * tb_v13479 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v13479; }
    { const char * tb_v13480 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v13480; }
    { const char * tb_v13481 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13481; }
    { const char * tb_v13482 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13482; }
    { const char * tb_v13483 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v13483; }
    { const char * tb_v13484 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13484; }
    { const char * tb_v13485 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13485; }
    { const char * tb_v13486 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v13486; }
    { const char * tb_v13487 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13487; }
    { const char * tb_v13488 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v13488; }
    { const char * tb_v13489 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v13489; }
    { const char * tb_v13490 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v13490; }
    { const char * tb_v13491 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13491; }
    { const char * tb_v13492 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13492; }
    { const char * tb_v13493 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v13493; }
    { const char * tb_v13494 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v13494; }
    { const char * tb_v13495 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v13495; }
    { const char * tb_v13496 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13496; }
    { const char * tb_v13497 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13497; }
    { const char * tb_v13498 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13498; }
    { const char * tb_v13499 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13499; }
    { const char * tb_v13500 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13500; }
    { const char * tb_v13501 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v13501; }
    { const char * tb_v13502 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v13502; }
    { const char * tb_v13503 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v13503; }
    { const char * tb_v13504 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v13504; }
    { const char * tb_v13505 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13505; }
    { const char * tb_v13506 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13506; }
    { const char * tb_v13507 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13507; }
    { const char * tb_v13508 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13508; }
    { const char * tb_v13509 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v13509; }
    { const char * tb_v13510 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13510; }
    { const char * tb_v13511 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v13511; }
    { const char * tb_v13512 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13512; }
    { const char * tb_v13513 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13513; }
    { const char * tb_v13514 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v13514; }
    { const char * tb_v13515 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13515; }
    { const char * tb_v13516 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13516; }
    { const char * tb_v13517 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13517; }
    { const char * tb_v13518 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v13518; }
    { const char * tb_v13519 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13519; }
    { const char * tb_v13520 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v13520; }
    { const char * tb_v13521 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v13521; }
    { const char * tb_v13522 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13522; }
    { const char * tb_v13523 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13523; }
    { const char * tb_v13524 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v13524; }
    { const char * tb_v13525 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v13525; }
    { const char * tb_v13526 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v13526; }
    { const char * tb_v13527 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13527; }
    { const char * tb_v13528 = "        fprintf(stderr, tb_tr(\"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\"), diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v13528; }
    { const char * tb_v13529 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13529; }
    { const char * tb_v13530 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13530; }
    { const char * tb_v13531 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v13531; }
    { const char * tb_v13532 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v13532; }
    { const char * tb_v13533 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v13533; }
    { const char * tb_v13534 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13534; }
    { const char * tb_v13535 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13535; }
    { const char * tb_v13536 = "// ---- несколько окон (1.3): window_new, window_use, window_close, window_shown ----\n"; *(const char * *)tb_grow(v_lines) = tb_v13536; }
    { const char * tb_v13537 = "// Главное окно (window_open) — номер 0. У каждого окна свои точки, размер, мышь, клавиши и глубина 3D.\n"; *(const char * *)tb_grow(v_lines) = tb_v13537; }
    { const char * tb_v13538 = "// Текущее окно лежит в обычных переменных (tb_px, tb_gw, tb_keys ...), остальные ждут в tb_wins.\n"; *(const char * *)tb_grow(v_lines) = tb_v13538; }
    { const char * tb_v13539 = "// Новые окна рисует процессор; видеокарта — у главного окна\n"; *(const char * *)tb_grow(v_lines) = tb_v13539; }
    { const char * tb_v13540 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v13540; }
    { const char * tb_v13541 = "    int used;\n"; *(const char * *)tb_grow(v_lines) = tb_v13541; }
    { const char * tb_v13542 = "    uint32_t *px; int gw, gh, gclosed, mx, my, mdown, mtap, wheel; double wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v13542; }
    { const char * tb_v13543 = "    int mside[2], mside_tap[2], ntyped; char typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v13543; }
    { const char * tb_v13544 = "    unsigned char keys[256], ktap[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v13544; }
    { const char * tb_v13545 = "    int new_w, new_h, resizable, gpu_on, zclr, gzclr; uint32_t *zb; long long zb_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13545; }
    { const char * tb_v13546 = "    TB_WPLAT\n"; *(const char * *)tb_grow(v_lines) = tb_v13546; }
    { const char * tb_v13547 = "} tb_wslot;\n"; *(const char * *)tb_grow(v_lines) = tb_v13547; }
    { const char * tb_v13548 = "static tb_wslot tb_wins[TB_WMAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v13548; }
    { const char * tb_v13549 = "#define TB_WFIELDS(X) X(px, tb_px) X(gw, tb_gw) X(gh, tb_gh) X(gclosed, tb_gclosed) X(mx, tb_mx) X(my, tb_my) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v13549; }
    { const char * tb_v13550 = "    X(mdown, tb_mdown) X(mtap, tb_mtap) X(wheel, tb_wheel) X(wheel_f, tb_wheel_f) X(ntyped, tb_ntyped) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v13550; }
    { const char * tb_v13551 = "    X(new_w, tb_new_w) X(new_h, tb_new_h) X(resizable, tb_resizable) X(gpu_on, tb_gpu_on) X(zclr, tb_zclr) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v13551; }
    { const char * tb_v13552 = "    X(gzclr, tb_gzclr) X(zb, tb_zb) X(zb_n, tb_zb_n)\n"; *(const char * *)tb_grow(v_lines) = tb_v13552; }
    { const char * tb_v13553 = "#define TB_WSAVE1(f, g) s->f = g;\n"; *(const char * *)tb_grow(v_lines) = tb_v13553; }
    { const char * tb_v13554 = "#define TB_WLOAD1(f, g) g = s->f;\n"; *(const char * *)tb_grow(v_lines) = tb_v13554; }
    { const char * tb_v13555 = "static void tb_wsave(tb_wslot *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13555; }
    { const char * tb_v13556 = "    TB_WFIELDS(TB_WSAVE1)\n"; *(const char * *)tb_grow(v_lines) = tb_v13556; }
    { const char * tb_v13557 = "    memcpy(s->mside, tb_mside, sizeof s->mside); memcpy(s->mside_tap, tb_mside_tap, sizeof s->mside_tap);\n"; *(const char * *)tb_grow(v_lines) = tb_v13557; }
    { const char * tb_v13558 = "    memcpy(s->typed, tb_typed, sizeof s->typed); memcpy(s->keys, tb_keys, sizeof s->keys); memcpy(s->ktap, tb_ktap, sizeof s->ktap);\n"; *(const char * *)tb_grow(v_lines) = tb_v13558; }
    { const char * tb_v13559 = "    TB_WPLAT_SAVE(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v13559; }
    { const char * tb_v13560 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13560; }
    { const char * tb_v13561 = "static void tb_wload(tb_wslot *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13561; }
    { const char * tb_v13562 = "    TB_WFIELDS(TB_WLOAD1)\n"; *(const char * *)tb_grow(v_lines) = tb_v13562; }
    { const char * tb_v13563 = "    memcpy(tb_mside, s->mside, sizeof s->mside); memcpy(tb_mside_tap, s->mside_tap, sizeof s->mside_tap);\n"; *(const char * *)tb_grow(v_lines) = tb_v13563; }
    { const char * tb_v13564 = "    memcpy(tb_typed, s->typed, sizeof s->typed); memcpy(tb_keys, s->keys, sizeof s->keys); memcpy(tb_ktap, s->ktap, sizeof s->ktap);\n"; *(const char * *)tb_grow(v_lines) = tb_v13564; }
    { const char * tb_v13565 = "    TB_WPLAT_LOAD(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v13565; }
    { const char * tb_v13566 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13566; }
    { const char * tb_v13567 = "TB_API int tb_wfind(uintptr_t h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13567; }
    { const char * tb_v13568 = "    for (int i = 0; i < tb_wn; i++) if (tb_wins[i].used && tb_whand[i] == h && h) return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v13568; }
    { const char * tb_v13569 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13569; }
    { const char * tb_v13570 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13570; }
    { const char * tb_v13571 = "// сделать окно i текущим: 3D, которое ждало, дорисовывается в прежнее окно\n"; *(const char * *)tb_grow(v_lines) = tb_v13571; }
    { const char * tb_v13572 = "TB_API void tb_wswitch(int i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13572; }
    { const char * tb_v13573 = "    if (i == tb_wcur || i < 0 || i >= tb_wn || !tb_wins[i].used) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13573; }
    { const char * tb_v13574 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13574; }
    { const char * tb_v13575 = "    tb_wsave(&tb_wins[tb_wcur]);\n"; *(const char * *)tb_grow(v_lines) = tb_v13575; }
    { const char * tb_v13576 = "    tb_wload(&tb_wins[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v13576; }
    { const char * tb_v13577 = "    tb_wcur = i;\n"; *(const char * *)tb_grow(v_lines) = tb_v13577; }
    { const char * tb_v13578 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13578; }
    { const char * tb_v13579 = "TB_API void tb_wmark_closed(int i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13579; }
    { const char * tb_v13580 = "    if (i == tb_wcur) tb_gclosed = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13580; }
    { const char * tb_v13581 = "    else if (i >= 0 && i < tb_wn) tb_wins[i].gclosed = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13581; }
    { const char * tb_v13582 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13582; }
    { const char * tb_v13583 = "TB_API int tb_gfx_open2(const char *title);\n"; *(const char * *)tb_grow(v_lines) = tb_v13583; }
    { const char * tb_v13584 = "TB_API void tb_gfx_show(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v13584; }
    { const char * tb_v13585 = "TB_API void tb_gfx_close2(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v13585; }
    { const char * tb_v13586 = "TB_API void tb_gfx_poll(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v13586; }
    { const char * tb_v13587 = "TB_API long long tb_window_new(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13587; }
    { const char * tb_v13588 = "    if (tb_wn == 0) { tb_err = \"сначала открой главное окно: window_open\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13588; }
    { const char * tb_v13589 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13589; }
    { const char * tb_v13590 = "    int i = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13590; }
    { const char * tb_v13591 = "    while (i < tb_wn && tb_wins[i].used) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v13591; }
    { const char * tb_v13592 = "    if (i >= TB_WMAX) { tb_err = \"окон больше 16 не бывает\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13592; }
    { const char * tb_v13593 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13593; }
    { const char * tb_v13594 = "        w = (long long)(w * tb_sc + 0.5); h = (long long)(h * tb_sc + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v13594; }
    { const char * tb_v13595 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v13595; }
    { const char * tb_v13596 = "        if (h > 8192) h = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v13596; }
    { const char * tb_v13597 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13597; }
    { const char * tb_v13598 = "    int was = tb_wcur;\n"; *(const char * *)tb_grow(v_lines) = tb_v13598; }
    { const char * tb_v13599 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13599; }
    { const char * tb_v13600 = "    tb_wsave(&tb_wins[was]);\n"; *(const char * *)tb_grow(v_lines) = tb_v13600; }
    { const char * tb_v13601 = "    tb_wslot *s = &tb_wins[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v13601; }
    { const char * tb_v13602 = "    memset(s, 0, sizeof *s);\n"; *(const char * *)tb_grow(v_lines) = tb_v13602; }
    { const char * tb_v13603 = "    s->gw = (int)w; s->gh = (int)h; s->zclr = s->gzclr = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13603; }
    { const char * tb_v13604 = "    s->px = calloc((size_t)w * h, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v13604; }
    { const char * tb_v13605 = "    tb_wload(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v13605; }
    { const char * tb_v13606 = "    int ok = tb_px && tb_gfx_open2(title);\n"; *(const char * *)tb_grow(v_lines) = tb_v13606; }
    { const char * tb_v13607 = "    if (ok) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13607; }
    { const char * tb_v13608 = "        s->used = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13608; }
    { const char * tb_v13609 = "        tb_whand[i] = tb_gfx_handle();\n"; *(const char * *)tb_grow(v_lines) = tb_v13609; }
    { const char * tb_v13610 = "        if (i >= tb_wn) tb_wn = i + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13610; }
    { const char * tb_v13611 = "        tb_wsave(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v13611; }
    { const char * tb_v13612 = "    } else free(tb_px);\n"; *(const char * *)tb_grow(v_lines) = tb_v13612; }
    { const char * tb_v13613 = "    tb_wload(&tb_wins[was]);\n"; *(const char * *)tb_grow(v_lines) = tb_v13613; }
