    { const char * tb_v13780 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13780; }
    { const char * tb_v13781 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v13781; }
