    { const char * tb_v13795 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13795; }
    { const char * tb_v13796 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13796; }
