    { const char * tb_v13810 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13810; }
    { const char * tb_v13811 = "// draw_shadow(x, y, w, h, r, size, c): мягкая тень скруглённого прямоугольника — внутри цвет c,\n"; *(const char * *)tb_grow(v_lines) = tb_v13811; }
    { const char * tb_v13812 = "// снаружи к size точкам сходит на нет. Корень считается только у кольца и углов, середина — простое смешивание.\n"; *(const char * *)tb_grow(v_lines) = tb_v13812; }
    { const char * tb_v13813 = "TB_API void tb_draw_shadow(long long x, long long y, long long w, long long h, long long r, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13813; }
    { const char * tb_v13814 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13814; }
