    { const char * tb_v13821 = "            long long a = (long long)((255 - ((c >> 24) & 255)) * f * f / (size / 2.0) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v13821; }
    { const char * tb_v13822 = "            if (a > 0) tb_gpu_rect(x - k, y - k + r, w + 2 * k, h + 2 * k - 2 * r, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v13822; }
    { const char * tb_v13823 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13823; }
    { const char * tb_v13824 = "        if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13824; }
    { const char * tb_v13825 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13825; }
    { const char * tb_v13826 = "    double hw = w / 2.0, hh = h / 2.0, cx = x + hw, cy = y + hh;\n"; *(const char * *)tb_grow(v_lines) = tb_v13826; }
    { const char * tb_v13827 = "    long long y0 = y - size < 0 ? 0 : y - size, y1 = y + h + size > tb_gh ? tb_gh : y + h + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v13827; }
    { const char * tb_v13828 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13828; }
