    { const char * tb_v13830 = "        if (dy < 0) dy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13830; }
    { const char * tb_v13831 = "        long long xa = x - size < 0 ? 0 : x - size, xb = x + w + size > tb_gw ? tb_gw : x + w + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v13831; }
    { const char * tb_v13832 = "        for (long long i = xa; i < xb; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13832; }
    { const char * tb_v13833 = "            double px = i + 0.5, dx = fabs(px - cx) - (hw - r);\n"; *(const char * *)tb_grow(v_lines) = tb_v13833; }
    { const char * tb_v13834 = "            if (dx < 0) dx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13834; }
    { const char * tb_v13835 = "            if (dx == 0 && dy == 0) { tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13835; }
    { const char * tb_v13836 = "            double d = sqrt(dx * dx + dy * dy) - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v13836; }
    { const char * tb_v13837 = "            if (d >= size) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v13837; }
    { const char * tb_v13838 = "            double f = d <= 0 ? 1 : 1 - d / size;\n"; *(const char * *)tb_grow(v_lines) = tb_v13838; }
    { const char * tb_v13839 = "            tb_cover(i, j, (uint32_t)c, f * f);\n"; *(const char * *)tb_grow(v_lines) = tb_v13839; }
