    { const char * tb_v13842 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13842; }
    { const char * tb_v13843 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v13843; }
    { const char * tb_v13844 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13844; }
    { const char * tb_v13845 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v13845; }
    { const char * tb_v13846 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13846; }
    { const char * tb_v13847 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v13847; }
    { const char * tb_v13848 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v13848; }
    { const char * tb_v13849 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13849; }
    { const char * tb_v13850 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v13850; }
    { const char * tb_v13851 = "        const char *e = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v13851; }
    { const char * tb_v13852 = "        while (*e && *e != ' ' && *e != ',') e++;\n"; *(const char * *)tb_grow(v_lines) = tb_v13852; }
    { const char * tb_v13853 = "        for (int i = 0; i < 9; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v13853; }
    { const char * tb_v13854 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v13854; }
    { const char * tb_v13855 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v13855; }
    { const char * tb_v13856 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13856; }
    { const char * tb_v13857 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v13857; }
    { const char * tb_v13858 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13858; }
    { const char * tb_v13859 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba)\n"; *(const char * *)tb_grow(v_lines) = tb_v13859; }
    { const char * tb_v13860 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13860; }
    { const char * tb_v13861 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13861; }
    { const char * tb_v13862 = "    if (!tb_px || w <= 0 || h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13862; }
    { const char * tb_v13863 = "    int m = tb_corners(corners);\n"; *(const char * *)tb_grow(v_lines) = tb_v13863; }
    { const char * tb_v13864 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13864; }
    { const char * tb_v13865 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v13865; }
    { const char * tb_v13866 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v13866; }
    { const char * tb_v13867 = "    if (tb_gpu_on) {   // видеокарта: пока без сглаживания\n"; *(const char * *)tb_grow(v_lines) = tb_v13867; }
    { const char * tb_v13868 = "        tb_gpu_rect(x + r, y, w - 2 * r, h, c); tb_gpu_rect(x, y + r, r, h - 2 * r, c); tb_gpu_rect(x + w - r, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13868; }
    { const char * tb_v13869 = "        tb_gpu_circle(x + r, y + r, r, c); tb_gpu_circle(x + w - 1 - r, y + r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13869; }
    { const char * tb_v13870 = "        tb_gpu_circle(x + r, y + h - 1 - r, r, c); tb_gpu_circle(x + w - 1 - r, y + h - 1 - r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13870; }
    { const char * tb_v13871 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13871; }
    { const char * tb_v13872 = "    if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13872; }
    { const char * tb_v13873 = "    uint32_t cc = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v13873; }
    { const char * tb_v13874 = "    long long y0 = y < 0 ? 0 : y, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v13874; }
    { const char * tb_v13875 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13875; }
    { const char * tb_v13876 = "        long long row = j - y;\n"; *(const char * *)tb_grow(v_lines) = tb_v13876; }
    { const char * tb_v13877 = "        int top = row < r, bot = row >= h - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v13877; }
    { const char * tb_v13878 = "        int lc = (top && (m & 1)) || (bot && (m & 4)), rc = (top && (m & 2)) || (bot && (m & 8));\n"; *(const char * *)tb_grow(v_lines) = tb_v13878; }
    { const char * tb_v13879 = "        double cy = top ? y + r - 0.5 : y + h - r - 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v13879; }
    { const char * tb_v13880 = "        // середина строки — сплошняком\n"; *(const char * *)tb_grow(v_lines) = tb_v13880; }
    { const char * tb_v13881 = "        long long a = x + (lc ? r : 0), b = x + w - (rc ? r : 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13881; }
    { const char * tb_v13882 = "        if (a < 0) a = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13882; }
