    { const char * tb_v13884 = "        if ((cc >> 24) & 255) { for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], cc); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13884; }
    { const char * tb_v13885 = "        else for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = cc & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v13885; }
    { const char * tb_v13886 = "        // углы: покрытие точки по расстоянию до центра угла\n"; *(const char * *)tb_grow(v_lines) = tb_v13886; }
    { const char * tb_v13887 = "        for (int side = 0; side < 2; side++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13887; }
    { const char * tb_v13888 = "            if (!(side ? rc : lc)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v13888; }
