    { const char * tb_v13890 = "            long long i0 = side ? x + w - r : x, i1 = side ? x + w : x + r;\n"; *(const char * *)tb_grow(v_lines) = tb_v13890; }
    { const char * tb_v13891 = "            for (long long i = i0; i < i1; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13891; }
    { const char * tb_v13892 = "                double dx = i + 0.5 - (cx + 0.5), dy = j + 0.5 - (cy + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v13892; }
    { const char * tb_v13893 = "                double d = sqrt(dx * dx + dy * dy);\n"; *(const char * *)tb_grow(v_lines) = tb_v13893; }
    { const char * tb_v13894 = "                tb_cover(i, j, cc, r - d + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v13894; }
    { const char * tb_v13895 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v13895; }
