    { const char * tb_v14045 = "// точка картинки × оттенок (свет): (т · о + 127) / 255 по каждому цвету\n"; *(const char * *)tb_grow(v_lines) = tb_v14045; }
    { const char * tb_v14046 = "TB_INL uint32_t tb_tex_tint(uint32_t t, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14046; }
