    { const char * tb_v14102 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v14102; }
    { const char * tb_v14103 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14103; }
