    { const char * tb_v14147 = "            if ((v >> 24) >= 128) tb_px[(y + j) * tb_gw + x + i] = v & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v14147; }
    { const char * tb_v14148 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14148; }
    { const char * tb_v14149 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14149; }
    { const char * tb_v14150 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14150; }
    { const char * tb_v14151 = "// то же с настоящей прозрачностью: точка = округл(цвет * a / 255) + округл(фон * (255 - a) / 255).\n"; *(const char * *)tb_grow(v_lines) = tb_v14151; }
    { const char * tb_v14152 = "// Две части округляются порознь: так получается одинаково на любой видеокарте (шейдер считает первую часть сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v14152; }
    { const char * tb_v14153 = "TB_API void tb_draw_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14153; }
    { const char * tb_v14154 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14154; }
    { const char * tb_v14155 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14155; }
    { const char * tb_v14156 = "    if (tb_gpu_on) tb_gpu_image_a(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v14156; }
    { const char * tb_v14157 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14157; }
    { const char * tb_v14158 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v14158; }
    { const char * tb_v14159 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v14159; }
    { const char * tb_v14160 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v14160; }
    { const char * tb_v14161 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v14161; }
    { const char * tb_v14162 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14162; }
    { const char * tb_v14163 = "            uint32_t v = src[j * im->w + i], a = v >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v14163; }
    { const char * tb_v14164 = "            if (a == 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v14164; }
    { const char * tb_v14165 = "            uint32_t *d = &tb_px[(y + j) * tb_gw + x + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14165; }
    { const char * tb_v14166 = "            if (a == 255) { *d = v & 0xFFFFFF; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14166; }
    { const char * tb_v14167 = "            uint32_t o = *d, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14167; }
    { const char * tb_v14168 = "            for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14168; }
    { const char * tb_v14169 = "                uint32_t sc = (v >> sh) & 255, dc = (o >> sh) & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14169; }
    { const char * tb_v14170 = "                uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14170; }
    { const char * tb_v14171 = "                r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v14171; }
    { const char * tb_v14172 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14172; }
    { const char * tb_v14173 = "            *d = r;\n"; *(const char * *)tb_grow(v_lines) = tb_v14173; }
    { const char * tb_v14174 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14174; }
    { const char * tb_v14175 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14175; }
    { const char * tb_v14176 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14176; }
    { const char * tb_v14177 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v14177; }
    { const char * tb_v14178 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14178; }
    { const char * tb_v14179 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14179; }
    { const char * tb_v14180 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14180; }
    { const char * tb_v14181 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14181; }
    { const char * tb_v14182 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v14182; }
    { const char * tb_v14183 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v14183; }
    { const char * tb_v14184 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14184; }
    { const char * tb_v14185 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14185; }
    { const char * tb_v14186 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v14186; }
    { const char * tb_v14187 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14187; }
    { const char * tb_v14188 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v14188; }
    { const char * tb_v14189 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v14189; }
    { const char * tb_v14190 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14190; }
    { const char * tb_v14191 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v14191; }
    { const char * tb_v14192 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v14192; }
    { const char * tb_v14193 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v14193; }
    { const char * tb_v14194 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14194; }
    { const char * tb_v14195 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14195; }
    { const char * tb_v14196 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v14196; }
    { const char * tb_v14197 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v14197; }
    { const char * tb_v14198 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v14198; }
    { const char * tb_v14199 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v14199; }
    { const char * tb_v14200 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v14200; }
    { const char * tb_v14201 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v14201; }
    { const char * tb_v14202 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v14202; }
    { const char * tb_v14203 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14203; }
    { const char * tb_v14204 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v14204; }
    { const char * tb_v14205 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14205; }
    { const char * tb_v14206 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14206; }
    { const char * tb_v14207 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14207; }
    { const char * tb_v14208 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v14208; }
    { const char * tb_v14209 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14209; }
    { const char * tb_v14210 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14210; }
    { const char * tb_v14211 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v14211; }
    { const char * tb_v14212 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v14212; }
    { const char * tb_v14213 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v14213; }
    { const char * tb_v14214 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v14214; }
    { const char * tb_v14215 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v14215; }
    { const char * tb_v14216 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v14216; }
    { const char * tb_v14217 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v14217; }
    { const char * tb_v14218 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v14218; }
    { const char * tb_v14219 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v14219; }
    { const char * tb_v14220 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v14220; }
    { const char * tb_v14221 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v14221; }
    { const char * tb_v14222 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v14222; }
    { const char * tb_v14223 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v14223; }
    { const char * tb_v14224 = "typedef struct { int parent, useq; double piv[3], rot[3], mv[3], q[4]; } tb_bone_t;   // кость: родитель, сустав, поворот (или кватернион q, useq), сдвиг\n"; *(const char * *)tb_grow(v_lines) = tb_v14224; }
    { const char * tb_v14225 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v14225; }
    { const char * tb_v14226 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v14226; }
    { const char * tb_v14227 = "    int32_t *nrm; long long nrmcap; int nrmok;   // нормаль каждого треугольника в сетке (× 2^14), для света\n"; *(const char * *)tb_grow(v_lines) = tb_v14227; }
    { const char * tb_v14228 = "    double *uv; long long tex;   // картинка сетки (mesh_image, -1 — нет) и (u, v) трёх углов треугольника (NAN — без картинки)\n"; *(const char * *)tb_grow(v_lines) = tb_v14228; }
    { const char * tb_v14229 = "    long long nch, *chr; double *chs, bs[4]; int chok;\n"; *(const char * *)tb_grow(v_lines) = tb_v14229; }
    { const char * tb_v14230 = "    int smooth, alpha, cnok; double shine, glow; double *cn; long long cncap;   // плавный свет, прозрачность 0…255, блеск, свечение; нормали в углах\n"; *(const char * *)tb_grow(v_lines) = tb_v14230; }
    { const char * tb_v14231 = "    tb_bone_t *bones; long long nb, capb; int16_t *sb; float *sw;\n"; *(const char * *)tb_grow(v_lines) = tb_v14231; }
    { const char * tb_v14232 = "    int shp, shc, shok; float shv[16]; int shimg[4]; int noshadow; float *shvd; long long shvn, shvcap, shused; void *shvb;\n"; *(const char * *)tb_grow(v_lines) = tb_v14232; }
    { const char * tb_v14233 = "    long long lod; double lodd, far, ub[4]; int hasub; } tb_mesh;   // lod — сетка вместо этой дальше lodd; far — дальше не рисовать; ub — свой шар (mesh_bounds)   // gpu func: шейдер точки и углов (-1 — обычный), настройки, углы для видеокарты     // кости и у каждого угла до 4 костей с весами   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v14233; }
    { const char * tb_v14234 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14234; }
    { const char * tb_v14235 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14235; }
    { const char * tb_v14236 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v14236; }
    { const char * tb_v14237 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v14237; }
    { const char * tb_v14238 = "TB_API long long *tb_mfree = 0, tb_nmfree = 0, tb_capmfree = 0;   // номера сеток после mesh_free: mesh_new берёт их снова\n"; *(const char * *)tb_grow(v_lines) = tb_v14238; }
    { const char * tb_v14239 = "static void tb_mesh_reset(long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14239; }
    { const char * tb_v14240 = "    memset(&tb_meshes[i], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v14240; }
    { const char * tb_v14241 = "    tb_meshes[i].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14241; }
    { const char * tb_v14242 = "    tb_meshes[i].tex = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14242; }
    { const char * tb_v14243 = "    tb_meshes[i].alpha = 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14243; }
    { const char * tb_v14244 = "    tb_meshes[i].shp = tb_meshes[i].shc = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14244; }
    { const char * tb_v14245 = "    tb_meshes[i].shused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14245; }
    { const char * tb_v14246 = "    tb_meshes[i].lod = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14246; }
    { const char * tb_v14247 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14247; }
    { const char * tb_v14248 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14248; }
    { const char * tb_v14249 = "    if (tb_nmfree > 0) { long long i = tb_mfree[--tb_nmfree]; tb_mesh_reset(i); return i; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14249; }
    { const char * tb_v14250 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14250; }
    { const char * tb_v14251 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v14251; }
    { const char * tb_v14252 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v14252; }
    { const char * tb_v14253 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14253; }
    { const char * tb_v14254 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v14254; }
    { const char * tb_v14255 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14255; }
    { const char * tb_v14256 = "    tb_meshes[tb_nmesh].tex = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14256; }
    { const char * tb_v14257 = "    tb_meshes[tb_nmesh].alpha = 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14257; }
    { const char * tb_v14258 = "    tb_meshes[tb_nmesh].shp = tb_meshes[tb_nmesh].shc = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14258; }
    { const char * tb_v14259 = "    tb_meshes[tb_nmesh].shused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14259; }
    { const char * tb_v14260 = "    tb_meshes[tb_nmesh].lod = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14260; }
    { const char * tb_v14261 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14261; }
    { const char * tb_v14262 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14262; }
    { const char * tb_v14263 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14263; }
    { const char * tb_v14264 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14264; }
    { const char * tb_v14265 = "    memcpy(w, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v14265; }
    { const char * tb_v14266 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14266; }
    { const char * tb_v14267 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v14267; }
    { const char * tb_v14268 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14268; }
    { const char * tb_v14269 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v14269; }
    { const char * tb_v14270 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14270; }
    { const char * tb_v14271 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v14271; }
    { const char * tb_v14272 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14272; }
    { const char * tb_v14273 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v14273; }
    { const char * tb_v14274 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14274; }
    { const char * tb_v14275 = "        for (long long i = 0; i < nc; i++) nk[i] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14275; }
    { const char * tb_v14276 = "        for (long long v = 0; v < m->nv; v++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14276; }
