    { const char * tb_v14596 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14596; }
    { const char * tb_v14597 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v14597; }
