    { const char * tb_v14622 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v14622; }
    { const char * tb_v14623 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v14623; }
    { const char * tb_v14624 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v14624; }
    { const char * tb_v14625 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14625; }
    { const char * tb_v14626 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v14626; }
    { const char * tb_v14627 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v14627; }
    { const char * tb_v14628 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14628; }
    { const char * tb_v14629 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14629; }
    { const char * tb_v14630 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v14630; }
    { const char * tb_v14631 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14631; }
    { const char * tb_v14632 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v14632; }
    { const char * tb_v14633 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v14633; }
    { const char * tb_v14634 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14634; }
    { const char * tb_v14635 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14635; }
    { const char * tb_v14636 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v14636; }
    { const char * tb_v14637 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14637; }
    { const char * tb_v14638 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14638; }
    { const char * tb_v14639 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14639; }
    { const char * tb_v14640 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14640; }
    { const char * tb_v14641 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v14641; }
    { const char * tb_v14642 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14642; }
    { const char * tb_v14643 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14643; }
    { const char * tb_v14644 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v14644; }
    { const char * tb_v14645 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v14645; }
    { const char * tb_v14646 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14646; }
    { const char * tb_v14647 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14647; }
    { const char * tb_v14648 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v14648; }
    { const char * tb_v14649 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14649; }
