    { const char * tb_v14651 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14651; }
    { const char * tb_v14652 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники по две строки:\n"; *(const char * *)tb_grow(v_lines) = tb_v14652; }
    { const char * tb_v14653 = "// (номера углов, цвет) и (нормаль × 2^14, -1)\n"; *(const char * *)tb_grow(v_lines) = tb_v14653; }
    { const char * tb_v14654 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14654; }
