    { const char * tb_v14688 = "    if (cc[2] + rad < 205.0 / 4096) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14688; }
    { const char * tb_v14689 = "    double hw = tb_gw / 2.0 + 2, hh = tb_gh / 2.0 + 2, lx = sqrt(f * f + hw * hw), ly = sqrt(f * f + hh * hh);\n"; *(const char * *)tb_grow(v_lines) = tb_v14689; }
    { const char * tb_v14690 = "    if ((f * cc[0] - hw * cc[2]) / lx > rad || (-f * cc[0] - hw * cc[2]) / lx > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14690; }
    { const char * tb_v14691 = "    if ((f * cc[1] - hh * cc[2]) / ly > rad || (-f * cc[1] - hh * cc[2]) / ly > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14691; }
    { const char * tb_v14692 = "    double zmin = cc[2] - rad;\n"; *(const char * *)tb_grow(v_lines) = tb_v14692; }
