    { const char * tb_v14912 = "// Сетка с этими вещами считается на процессоре дробями: кости, место каждого угла в мире, свет каждого угла\n"; *(const char * *)tb_grow(v_lines) = tb_v14912; }
    { const char * tb_v14913 = "// (солнце, лампы, блик), место в тени, обрезка у камеры и рамкой вокруг окна. А точки внутри треугольника —\n"; *(const char * *)tb_grow(v_lines) = tb_v14913; }
    { const char * tb_v14914 = "// целыми числами одной формулой и на процессоре (tb_lit_px), и на видеокарте (tbl.frag, tb_fragl в tb3.metal):\n"; *(const char * *)tb_grow(v_lines) = tb_v14914; }
    { const char * tb_v14915 = "// значение в точке = (e0·v0·W0 + e1·v1·W1 + e2·v2·W2) / (e0·W0 + e1·W1 + e2·W2), где e — те же «стороны», что решают,\n"; *(const char * *)tb_grow(v_lines) = tb_v14915; }
    { const char * tb_v14916 = "// внутри ли точка (tb_tri_edge), а W — 1/z угла (так свет и тени ложатся с перспективой). Кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v14916; }
    { const char * tb_v14917 = "TB_INL double tb_fmin(double a, double b) { return a < b ? a : b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14917; }
    { const char * tb_v14918 = "TB_INL double tb_fmax(double a, double b) { return a > b ? a : b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14918; }
    { const char * tb_v14919 = "typedef struct { int on, spot; double p[3], d[3], c0, c1, range, col[3]; } tb_lamp_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v14919; }
    { const char * tb_v14920 = "TB_API tb_lamp_t tb_lamps[8];\n"; *(const char * *)tb_grow(v_lines) = tb_v14920; }
    { const char * tb_v14921 = "TB_API int tb_nlamps = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14921; }
    { const char * tb_v14922 = "TB_API double tb_amb0 = 0;               // фон, когда солнца нет (sunlight(0, 0, 0, фон)), а лампы горят\n"; *(const char * *)tb_grow(v_lines) = tb_v14922; }
    { const char * tb_v14923 = "TB_API int tb_fog_on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14923; }
    { const char * tb_v14924 = "TB_API uint32_t tb_fog_c = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14924; }
    { const char * tb_v14925 = "TB_API double tb_fog_n = 0, tb_fog_f = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14925; }
    { const char * tb_v14926 = "TB_API double tb_sh_size = 0;            // тени: сторона квадрата вокруг камеры (0 — теней нет)\n"; *(const char * *)tb_grow(v_lines) = tb_v14926; }
    { const char * tb_v14927 = "TB_API uint32_t *tb_sm = 0;              // карта теней (процессор): глубина от солнца, 0…65535\n"; *(const char * *)tb_grow(v_lines) = tb_v14927; }
    { const char * tb_v14928 = "TB_API long long tb_sm_ver = 0;          // номер карты (растёт при каждой новой)\n"; *(const char * *)tb_grow(v_lines) = tb_v14928; }
    { const char * tb_v14929 = "TB_API int tb_sm_live = 0;               // карта этой сцены готова: треугольники сцены знают про тени\n"; *(const char * *)tb_grow(v_lines) = tb_v14929; }
    { const char * tb_v14930 = "TB_API double tb_smC[3], tb_smR[3], tb_smU[3], tb_smF[3], tb_smT;   // квадрат теней: центр, оси, размер точки карты\n"; *(const char * *)tb_grow(v_lines) = tb_v14930; }
    { const char * tb_v14931 = "// видеокарта: какая карта теней лежит в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v14931; }
    { const char * tb_v14932 = "TB_API long long tb_gsm_batch = -1, tb_gsm_ver = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14932; }
    { const char * tb_v14933 = "TB_INL int tb_lit_on(void) { return tb_lamb >= 0 || tb_nlamps > 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14933; }
    { const char * tb_v14934 = "// сетка рисуется новым путём? (свои настройки сетки или что-то общее для всей сцены)\n"; *(const char * *)tb_grow(v_lines) = tb_v14934; }
    { const char * tb_v14935 = "TB_INL int tb_lit_mesh(const tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14935; }
    { const char * tb_v14936 = "    return m->smooth || m->shine > 0 || m->glow > 0 || m->alpha < 255 || m->nb > 0 || tb_nlamps > 0 || tb_fog_on || tb_sh_size > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14936; }
    { const char * tb_v14937 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14937; }
    { const char * tb_v14938 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v14938; }
    { const char * tb_v14939 = "// ---- лампы, туман, тени ----\n"; *(const char * *)tb_grow(v_lines) = tb_v14939; }
    { const char * tb_v14940 = "static void tb_lamps_count(void) { tb_nlamps = 0; for (int i = 0; i < 8; i++) tb_nlamps += tb_lamps[i].on; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14940; }
    { const char * tb_v14941 = "static void tb_rgb01(long long c, double *o) { o[0] = ((c >> 16) & 255) / 255.0; o[1] = ((c >> 8) & 255) / 255.0; o[2] = (c & 255) / 255.0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14941; }
    { const char * tb_v14942 = "TB_API void tb_point_light(long long n, double x, double y, double z, long long c, double range) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14942; }
    { const char * tb_v14943 = "    if (n < 0 || n > 7) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14943; }
    { const char * tb_v14944 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v14944; }
    { const char * tb_v14945 = "    tb_lamp_t *l = &tb_lamps[n];\n"; *(const char * *)tb_grow(v_lines) = tb_v14945; }
    { const char * tb_v14946 = "    l->on = range > 0 && fabs(x) < 1e300 && fabs(y) < 1e300 && fabs(z) < 1e300; l->spot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14946; }
    { const char * tb_v14947 = "    l->p[0] = x; l->p[1] = y; l->p[2] = z; l->range = range;\n"; *(const char * *)tb_grow(v_lines) = tb_v14947; }
    { const char * tb_v14948 = "    tb_rgb01(c, l->col);\n"; *(const char * *)tb_grow(v_lines) = tb_v14948; }
    { const char * tb_v14949 = "    tb_lamps_count();\n"; *(const char * *)tb_grow(v_lines) = tb_v14949; }
    { const char * tb_v14950 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14950; }
    { const char * tb_v14951 = "// фонарь: светит конусом шириной angle градусов в сторону (dx, dy, dz); край конуса мягкий\n"; *(const char * *)tb_grow(v_lines) = tb_v14951; }
    { const char * tb_v14952 = "TB_API void tb_spot_light(long long n, double x, double y, double z, double dx, double dy, double dz, double angle, long long c, double range) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14952; }
    { const char * tb_v14953 = "    if (n < 0 || n > 7) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14953; }
    { const char * tb_v14954 = "    tb_point_light(n, x, y, z, c, range);\n"; *(const char * *)tb_grow(v_lines) = tb_v14954; }
    { const char * tb_v14955 = "    tb_lamp_t *l = &tb_lamps[n];\n"; *(const char * *)tb_grow(v_lines) = tb_v14955; }
    { const char * tb_v14956 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v14956; }
    { const char * tb_v14957 = "    if (!(d > 1e-12) || !(angle > 0)) { l->on = 0; tb_lamps_count(); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14957; }
    { const char * tb_v14958 = "    if (angle > 179) angle = 179;\n"; *(const char * *)tb_grow(v_lines) = tb_v14958; }
    { const char * tb_v14959 = "    l->spot = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14959; }
    { const char * tb_v14960 = "    l->d[0] = dx / d; l->d[1] = dy / d; l->d[2] = dz / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v14960; }
    { const char * tb_v14961 = "    double h = angle / 2 * 3.14159265358979323846 / 180;\n"; *(const char * *)tb_grow(v_lines) = tb_v14961; }
    { const char * tb_v14962 = "    l->c1 = cos(h); l->c0 = cos(h * 0.75);   // от c0 к краю c1 свет плавно гаснет\n"; *(const char * *)tb_grow(v_lines) = tb_v14962; }
    { const char * tb_v14963 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14963; }
    { const char * tb_v14964 = "TB_API void tb_light_off(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14964; }
    { const char * tb_v14965 = "    if (n < 0 || n > 7) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14965; }
    { const char * tb_v14966 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v14966; }
    { const char * tb_v14967 = "    tb_lamps[n].on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14967; }
    { const char * tb_v14968 = "    tb_lamps_count();\n"; *(const char * *)tb_grow(v_lines) = tb_v14968; }
    { const char * tb_v14969 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14969; }
    { const char * tb_v14970 = "// туман: с расстояния near цвет уходит в c, дальше far — весь c; fog(0, 0, 0) — без тумана\n"; *(const char * *)tb_grow(v_lines) = tb_v14970; }
    { const char * tb_v14971 = "TB_API void tb_fog(long long c, double n, double f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14971; }
    { const char * tb_v14972 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v14972; }
    { const char * tb_v14973 = "    if (!(n >= 0)) n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14973; }
    { const char * tb_v14974 = "    tb_fog_on = f > n;\n"; *(const char * *)tb_grow(v_lines) = tb_v14974; }
    { const char * tb_v14975 = "    tb_fog_c = (uint32_t)c & 0xFFFFFF; tb_fog_n = n; tb_fog_f = f;\n"; *(const char * *)tb_grow(v_lines) = tb_v14975; }
    { const char * tb_v14976 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14976; }
    { const char * tb_v14977 = "// тени от солнца в квадрате size × size вокруг камеры; 0 — без теней\n"; *(const char * *)tb_grow(v_lines) = tb_v14977; }
    { const char * tb_v14978 = "TB_API void tb_shadows(double size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14978; }
    { const char * tb_v14979 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v14979; }
    { const char * tb_v14980 = "    tb_sh_size = size > 0 && size < 1e6 ? size : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14980; }
    { const char * tb_v14981 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14981; }
    { const char * tb_v14982 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v14982; }
    { const char * tb_v14983 = "// ---- свойства сетки ----\n"; *(const char * *)tb_grow(v_lines) = tb_v14983; }
    { const char * tb_v14984 = "TB_API void tb_mesh_smooth(long long id, int on) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14984; }
    { const char * tb_v14985 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14985; }
    { const char * tb_v14986 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v14986; }
    { const char * tb_v14987 = "    tb_meshes[id].smooth = on != 0; tb_meshes[id].cnok = 0; tb_meshes[id].shok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14987; }
    { const char * tb_v14988 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14988; }
    { const char * tb_v14989 = "TB_INL double tb_01(double v) { return v > 0 ? (v < 1 ? v : 1) : 0; }   // и NaN — 0\n"; *(const char * *)tb_grow(v_lines) = tb_v14989; }
    { const char * tb_v14990 = "TB_API void tb_mesh_shine(long long id, double s) { if (id >= 0 && id < tb_nmesh) tb_meshes[id].shine = tb_01(s); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14990; }
    { const char * tb_v14991 = "TB_API void tb_mesh_glow(long long id, double g) { if (id >= 0 && id < tb_nmesh) tb_meshes[id].glow = tb_01(g); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14991; }
    { const char * tb_v14992 = "TB_API void tb_mesh_alpha(long long id, double a) { if (id >= 0 && id < tb_nmesh) { tb_meshes[id].alpha = (int)tb_rnd(tb_01(a) * 255); tb_meshes[id].shok = 0; } }\n"; *(const char * *)tb_grow(v_lines) = tb_v14992; }
    { const char * tb_v14993 = "TB_API long long tb_mesh_count(long long id) { return id >= 0 && id < tb_nmesh ? tb_meshes[id].n : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14993; }
    { const char * tb_v14994 = "// стереть все треугольники сетки (кости остаются): сетку можно собрать заново — так меняют блоки мира\n"; *(const char * *)tb_grow(v_lines) = tb_v14994; }
    { const char * tb_v14995 = "TB_API void tb_mesh_clear(long long id) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14995; }
    { const char * tb_v14996 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14996; }
    { const char * tb_v14997 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v14997; }
    { const char * tb_v14998 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v14998; }
    { const char * tb_v14999 = "    if (tb_gpu_on && m->gused == tb_gbatch) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v14999; }
    { const char * tb_v15000 = "    free(m->hk); m->hk = 0; m->hcap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15000; }
    { const char * tb_v15001 = "    m->nv = 0; m->n = 0; m->big = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15001; }
    { const char * tb_v15002 = "    m->cullok = m->chok = m->nrmok = m->cnok = m->shok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15002; }
    { const char * tb_v15003 = "    tb_mesh_gdirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v15003; }
    { const char * tb_v15004 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15004; }
    { const char * tb_v15005 = "// mesh_free: сетка больше не нужна — память отдаётся, номер достанется следующему mesh_new\n"; *(const char * *)tb_grow(v_lines) = tb_v15005; }
    { const char * tb_v15006 = "// (старый номер больше не трогай: он будет у другой сетки). Для подгрузки мира кусками\n"; *(const char * *)tb_grow(v_lines) = tb_v15006; }
    { const char * tb_v15007 = "TB_API void tb_mesh_free(long long id) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15007; }
    { const char * tb_v15008 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v15008; }
    { const char * tb_v15009 = "    for (long long i = 0; i < tb_nmfree; i++) if (tb_mfree[i] == id) return;   // уже отдана\n"; *(const char * *)tb_grow(v_lines) = tb_v15009; }
    { const char * tb_v15010 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v15010; }
    { const char * tb_v15011 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v15011; }
    { const char * tb_v15012 = "    if (tb_gpu_on && (m->gused == tb_gbatch || m->shused == tb_gbatch)) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v15012; }
    { const char * tb_v15013 = "    if (m->shvb) tb_gpu_sh_vbuf(m->shvb, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v15013; }
    { const char * tb_v15014 = "    if (m->shp < 0 && m->shc < 0) tb_mesh_gdirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v15014; }
    { const char * tb_v15015 = "    free(m->v); free(m->t); free(m->c); free(m->hk); free(m->vi); free(m->nrm); free(m->uv); free(m->chr); free(m->chs);\n"; *(const char * *)tb_grow(v_lines) = tb_v15015; }
    { const char * tb_v15016 = "    free(m->cn); free(m->bones); free(m->sb); free(m->sw); free(m->shvd);\n"; *(const char * *)tb_grow(v_lines) = tb_v15016; }
    { const char * tb_v15017 = "    for (long long i = 0; i < tb_nmesh; i++) if (tb_meshes[i].lod == id) tb_meshes[i].lod = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v15017; }
    { const char * tb_v15018 = "    tb_mesh_reset(id);\n"; *(const char * *)tb_grow(v_lines) = tb_v15018; }
    { const char * tb_v15019 = "    if (tb_nmfree == tb_capmfree) { tb_capmfree = tb_capmfree ? tb_capmfree * 2 : 64; tb_mfree = (long long *)realloc(tb_mfree, sizeof(long long) * (size_t)tb_capmfree); }\n"; *(const char * *)tb_grow(v_lines) = tb_v15019; }
    { const char * tb_v15020 = "    tb_mfree[tb_nmfree++] = id;\n"; *(const char * *)tb_grow(v_lines) = tb_v15020; }
    { const char * tb_v15021 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15021; }
    { const char * tb_v15022 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v15022; }
    { const char * tb_v15023 = "// ---- кости ----\n"; *(const char * *)tb_grow(v_lines) = tb_v15023; }
    { const char * tb_v15024 = "// bone_add: сустав в точке (x, y, z) сетки, родитель — другая кость (-1 — нет). Углы сетки берут кости\n"; *(const char * *)tb_grow(v_lines) = tb_v15024; }
    { const char * tb_v15025 = "// по весам (bone_weight, bone_box); bone_turn / bone_move двигают кость вокруг сустава вместе с детьми\n"; *(const char * *)tb_grow(v_lines) = tb_v15025; }
    { const char * tb_v15026 = "TB_API long long tb_bone_add(long long id, long long parent, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15026; }
    { const char * tb_v15027 = "    if (id < 0 || id >= tb_nmesh) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v15027; }
    { const char * tb_v15028 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v15028; }
    { const char * tb_v15029 = "    if (parent < -1 || parent >= m->nb || m->nb >= 32767) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v15029; }
    { const char * tb_v15030 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v15030; }
    { const char * tb_v15031 = "    if (m->nb == m->capb) { m->capb = m->capb ? m->capb * 2 : 8; m->bones = (tb_bone_t *)realloc(m->bones, sizeof(tb_bone_t) * (size_t)m->capb); }\n"; *(const char * *)tb_grow(v_lines) = tb_v15031; }
    { const char * tb_v15032 = "    tb_bone_t *b = &m->bones[m->nb];\n"; *(const char * *)tb_grow(v_lines) = tb_v15032; }
    { const char * tb_v15033 = "    memset(b, 0, sizeof *b);\n"; *(const char * *)tb_grow(v_lines) = tb_v15033; }
    { const char * tb_v15034 = "    b->parent = (int)parent; b->piv[0] = x; b->piv[1] = y; b->piv[2] = z;\n"; *(const char * *)tb_grow(v_lines) = tb_v15034; }
    { const char * tb_v15035 = "    m->shok = 0;   // углы для видеокарты — заново (номера костей)\n"; *(const char * *)tb_grow(v_lines) = tb_v15035; }
    { const char * tb_v15036 = "    return m->nb++;\n"; *(const char * *)tb_grow(v_lines) = tb_v15036; }
    { const char * tb_v15037 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15037; }
