    { const char * tb_v15658 = "    for (long long k = 0; k < m->nv; k++) for (int i = 0; i < 3; i++) { double v = m->v[3 * k + i]; if (v < lo[i]) lo[i] = v; if (v > hi[i]) hi[i] = v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v15658; }
