    { const char * tb_v16334 = "        {\"f1\", TB_K_F1}, {\"f2\", TB_K_F1 + 1}, {\"f3\", TB_K_F1 + 2}, {\"f4\", TB_K_F1 + 3}, {\"f5\", TB_K_F1 + 4}, {\"f6\", TB_K_F1 + 5},\n"; *(const char * *)tb_grow(v_lines) = tb_v16334; }
    { const char * tb_v16335 = "        {\"f7\", TB_K_F1 + 6}, {\"f8\", TB_K_F1 + 7}, {\"f9\", TB_K_F1 + 8}, {\"f10\", TB_K_F1 + 9}, {\"f11\", TB_K_F1 + 10}, {\"f12\", TB_K_F1 + 11} };\n"; *(const char * *)tb_grow(v_lines) = tb_v16335; }
    { const char * tb_v16336 = "    for (unsigned i = 0; i < sizeof names / sizeof names[0]; i++) if (strcmp(name, names[i].n) == 0) return tb_key_at(names[i].k);\n"; *(const char * *)tb_grow(v_lines) = tb_v16336; }
    { const char * tb_v16337 = "    if (name[0] && !name[1]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16337; }
    { const char * tb_v16338 = "        int ch = (unsigned char)name[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v16338; }
    { const char * tb_v16339 = "        if (ch >= 'a' && ch <= 'z') ch -= 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v16339; }
    { const char * tb_v16340 = "        return tb_key_at(ch);\n"; *(const char * *)tb_grow(v_lines) = tb_v16340; }
    { const char * tb_v16341 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16341; }
