    { const char * tb_v16345 = "TB_API long long tb_mouse_y(void) { return tb_my; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16345; }
    { const char * tb_v16346 = "TB_API int tb_mouse_down(void) { int d = tb_mdown || tb_mtap; tb_mtap = 0; return d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16346; }
    { const char * tb_v16347 = "TB_API long long tb_mouse_wheel(void) { int w = tb_wheel; tb_wheel = 0; return w; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16347; }
    { const char * tb_v16348 = "TB_API int tb_mouse_back(void) { int d = tb_mside[0] || tb_mside_tap[0]; tb_mside_tap[0] = 0; return d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16348; }
    { const char * tb_v16349 = "TB_API int tb_mouse_forward(void) { int d = tb_mside[1] || tb_mside_tap[1]; tb_mside_tap[1] = 0; return d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16349; }
    { const char * tb_v16350 = "// ---------- геймпад: pad_count(), pad_down(n, \"a\"), pad_axis(n, \"lx\") ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v16350; }
    { const char * tb_v16351 = "// Кнопки: a b x y l1 r1 l2 r2 l3 r3 start select home up down left right.\n"; *(const char * *)tb_grow(v_lines) = tb_v16351; }
    { const char * tb_v16352 = "// Оси (от -1 до 1, курки от 0 до 1): lx ly rx ry l2 r2. Вниз и вправо — плюс. n — номер геймпада с 0.\n"; *(const char * *)tb_grow(v_lines) = tb_v16352; }
    { const char * tb_v16353 = "// Mac — GameController, Windows — XInput, Linux — /dev/input/js*. В ядре без ОС геймпадов нет.\n"; *(const char * *)tb_grow(v_lines) = tb_v16353; }
    { const char * tb_v16354 = "enum { TB_PB_A, TB_PB_B, TB_PB_X, TB_PB_Y, TB_PB_L1, TB_PB_R1, TB_PB_L2, TB_PB_R2, TB_PB_L3, TB_PB_R3,\n"; *(const char * *)tb_grow(v_lines) = tb_v16354; }
    { const char * tb_v16355 = "       TB_PB_START, TB_PB_SELECT, TB_PB_HOME, TB_PB_UP, TB_PB_DOWN, TB_PB_LEFT, TB_PB_RIGHT, TB_PB_N };\n"; *(const char * *)tb_grow(v_lines) = tb_v16355; }
    { const char * tb_v16356 = "enum { TB_PA_LX, TB_PA_LY, TB_PA_RX, TB_PA_RY, TB_PA_L2, TB_PA_R2, TB_PA_N };\n"; *(const char * *)tb_grow(v_lines) = tb_v16356; }
    { const char * tb_v16357 = "#define TB_PADS 4\n"; *(const char * *)tb_grow(v_lines) = tb_v16357; }
    { const char * tb_v16358 = "typedef struct { int on; int b[TB_PB_N]; double a[TB_PA_N]; } tb_pad;\n"; *(const char * *)tb_grow(v_lines) = tb_v16358; }
    { const char * tb_v16359 = "TB_API tb_pad tb_pads[TB_PADS];\n"; *(const char * *)tb_grow(v_lines) = tb_v16359; }
    { const char * tb_v16360 = "TB_API long long tb_pad_t = -1000;   // когда опрашивали (мс): не чаще раза в 4 мс\n"; *(const char * *)tb_grow(v_lines) = tb_v16360; }
    { const char * tb_v16361 = "#if defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v16361; }
    { const char * tb_v16362 = "TB_API void tb_pad_poll(void) {}\n"; *(const char * *)tb_grow(v_lines) = tb_v16362; }
    { const char * tb_v16363 = "#elif defined(__APPLE__)\n"; *(const char * *)tb_grow(v_lines) = tb_v16363; }
    { const char * tb_v16364 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16364; }
    { const char * tb_v16365 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16365; }
    { const char * tb_v16366 = "    if (!tried) { tried = 1; dlopen(\"/System/Library/Frameworks/GameController.framework/GameController\", RTLD_LAZY); }\n"; *(const char * *)tb_grow(v_lines) = tb_v16366; }
    { const char * tb_v16367 = "    id cls = TB_CLS(\"GCController\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16367; }
    { const char * tb_v16368 = "    for (int p = 0; p < TB_PADS; p++) tb_pads[p].on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16368; }
    { const char * tb_v16369 = "    if (!cls) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v16369; }
    { const char * tb_v16370 = "    id all = TB_MSG(id, cls, \"controllers\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16370; }
    { const char * tb_v16371 = "    unsigned long n = all ? TB_MSG(unsigned long, all, \"count\") : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16371; }
    { const char * tb_v16372 = "    for (unsigned long i = 0; i < n && i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16372; }
    { const char * tb_v16373 = "        id c = TB_MSG1(id, all, \"objectAtIndex:\", unsigned long, i);\n"; *(const char * *)tb_grow(v_lines) = tb_v16373; }
    { const char * tb_v16374 = "        id g = TB_MSG(id, c, \"extendedGamepad\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16374; }
    { const char * tb_v16375 = "        if (!g) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16375; }
    { const char * tb_v16376 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v16376; }
    { const char * tb_v16377 = "        p->on = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16377; }
    { const char * tb_v16378 = "        static const char *bn[TB_PB_N] = { \"buttonA\", \"buttonB\", \"buttonX\", \"buttonY\", \"leftShoulder\", \"rightShoulder\",\n"; *(const char * *)tb_grow(v_lines) = tb_v16378; }
    { const char * tb_v16379 = "            \"leftTrigger\", \"rightTrigger\", \"leftThumbstickButton\", \"rightThumbstickButton\", \"buttonMenu\", \"buttonOptions\", \"buttonHome\", 0, 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16379; }
    { const char * tb_v16380 = "        for (int k = 0; k < TB_PB_N; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16380; }
    { const char * tb_v16381 = "            if (!bn[k]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16381; }
    { const char * tb_v16382 = "            if (!class_respondsToSelector(object_getClass(g), sel_getUid(bn[k]))) { p->b[k] = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16382; }
    { const char * tb_v16383 = "            id el = TB_MSG(id, g, bn[k]);\n"; *(const char * *)tb_grow(v_lines) = tb_v16383; }
    { const char * tb_v16384 = "            p->b[k] = el ? (int)TB_MSG(BOOL, el, \"isPressed\") : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16384; }
    { const char * tb_v16385 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v16385; }
    { const char * tb_v16386 = "        id dp = TB_MSG(id, g, \"dpad\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16386; }
    { const char * tb_v16387 = "        p->b[TB_PB_UP] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"up\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16387; }
    { const char * tb_v16388 = "        p->b[TB_PB_DOWN] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"down\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16388; }
    { const char * tb_v16389 = "        p->b[TB_PB_LEFT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"left\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16389; }
    { const char * tb_v16390 = "        p->b[TB_PB_RIGHT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"right\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16390; }
    { const char * tb_v16391 = "        id ls = TB_MSG(id, g, \"leftThumbstick\"), rs = TB_MSG(id, g, \"rightThumbstick\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16391; }
    { const char * tb_v16392 = "        p->a[TB_PA_LX] = TB_MSG(float, TB_MSG(id, ls, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16392; }
    { const char * tb_v16393 = "        p->a[TB_PA_LY] = -TB_MSG(float, TB_MSG(id, ls, \"yAxis\"), \"value\");   // у Apple вверх — плюс\n"; *(const char * *)tb_grow(v_lines) = tb_v16393; }
    { const char * tb_v16394 = "        p->a[TB_PA_RX] = TB_MSG(float, TB_MSG(id, rs, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16394; }
    { const char * tb_v16395 = "        p->a[TB_PA_RY] = -TB_MSG(float, TB_MSG(id, rs, \"yAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16395; }
    { const char * tb_v16396 = "        p->a[TB_PA_L2] = TB_MSG(float, TB_MSG(id, g, \"leftTrigger\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16396; }
    { const char * tb_v16397 = "        p->a[TB_PA_R2] = TB_MSG(float, TB_MSG(id, g, \"rightTrigger\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16397; }
    { const char * tb_v16398 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16398; }
    { const char * tb_v16399 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16399; }
    { const char * tb_v16400 = "#elif defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v16400; }
    { const char * tb_v16401 = "typedef struct { unsigned short buttons; unsigned char lt, rt; short lx, ly, rx, ry; } tb_xpad;\n"; *(const char * *)tb_grow(v_lines) = tb_v16401; }
    { const char * tb_v16402 = "typedef struct { unsigned long packet; tb_xpad pad; } tb_xstate;\n"; *(const char * *)tb_grow(v_lines) = tb_v16402; }
    { const char * tb_v16403 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16403; }
    { const char * tb_v16404 = "    static unsigned long (__stdcall *get)(unsigned long, tb_xstate *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16404; }
    { const char * tb_v16405 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16405; }
    { const char * tb_v16406 = "    if (!tried) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16406; }
    { const char * tb_v16407 = "        tried = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16407; }
    { const char * tb_v16408 = "        HMODULE h = LoadLibraryA(\"xinput1_4.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16408; }
    { const char * tb_v16409 = "        if (!h) h = LoadLibraryA(\"xinput9_1_0.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16409; }
    { const char * tb_v16410 = "        if (h) get = (unsigned long (__stdcall *)(unsigned long, tb_xstate *))GetProcAddress(h, \"XInputGetState\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16410; }
    { const char * tb_v16411 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16411; }
    { const char * tb_v16412 = "    for (int i = 0; i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16412; }
    { const char * tb_v16413 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v16413; }
    { const char * tb_v16414 = "        tb_xstate st; memset(&st, 0, sizeof st);\n"; *(const char * *)tb_grow(v_lines) = tb_v16414; }
    { const char * tb_v16415 = "        p->on = get && get((unsigned long)i, &st) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16415; }
    { const char * tb_v16416 = "        if (!p->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16416; }
    { const char * tb_v16417 = "        unsigned short w = st.pad.buttons;\n"; *(const char * *)tb_grow(v_lines) = tb_v16417; }
    { const char * tb_v16418 = "        static const unsigned short bit[TB_PB_N] = { 0x1000, 0x2000, 0x4000, 0x8000, 0x0100, 0x0200, 0, 0, 0x0040, 0x0080, 0x0010, 0x0020, 0, 0x0001, 0x0002, 0x0004, 0x0008 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16418; }
    { const char * tb_v16419 = "        for (int k = 0; k < TB_PB_N; k++) p->b[k] = bit[k] ? (w & bit[k]) != 0 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16419; }
    { const char * tb_v16420 = "        p->b[TB_PB_L2] = st.pad.lt > 30; p->b[TB_PB_R2] = st.pad.rt > 30;\n"; *(const char * *)tb_grow(v_lines) = tb_v16420; }
    { const char * tb_v16421 = "        p->a[TB_PA_LX] = st.pad.lx / 32767.0; p->a[TB_PA_LY] = -st.pad.ly / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16421; }
    { const char * tb_v16422 = "        p->a[TB_PA_RX] = st.pad.rx / 32767.0; p->a[TB_PA_RY] = -st.pad.ry / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16422; }
    { const char * tb_v16423 = "        p->a[TB_PA_L2] = st.pad.lt / 255.0; p->a[TB_PA_R2] = st.pad.rt / 255.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16423; }
    { const char * tb_v16424 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16424; }
    { const char * tb_v16425 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16425; }
    { const char * tb_v16426 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v16426; }
    { const char * tb_v16427 = "#include <fcntl.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v16427; }
    { const char * tb_v16428 = "TB_API int tb_pad_fd[TB_PADS] = { -1, -1, -1, -1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16428; }
    { const char * tb_v16429 = "TB_API long long tb_pad_look = -100000;\n"; *(const char * *)tb_grow(v_lines) = tb_v16429; }
    { const char * tb_v16430 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16430; }
    { const char * tb_v16431 = "    // новые геймпады ищем раз в 2 секунды\n"; *(const char * *)tb_grow(v_lines) = tb_v16431; }
    { const char * tb_v16432 = "    long long now = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v16432; }
    { const char * tb_v16433 = "    if (now - tb_pad_look > 2000) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16433; }
    { const char * tb_v16434 = "        tb_pad_look = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v16434; }
    { const char * tb_v16435 = "        for (int i = 0; i < TB_PADS; i++) if (tb_pad_fd[i] < 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16435; }
    { const char * tb_v16436 = "            char path[32]; snprintf(path, sizeof path, \"/dev/input/js%d\", i);\n"; *(const char * *)tb_grow(v_lines) = tb_v16436; }
    { const char * tb_v16437 = "            tb_pad_fd[i] = open(path, O_RDONLY | O_NONBLOCK);\n"; *(const char * *)tb_grow(v_lines) = tb_v16437; }
    { const char * tb_v16438 = "            if (tb_pad_fd[i] >= 0) memset(&tb_pads[i], 0, sizeof tb_pads[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v16438; }
    { const char * tb_v16439 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v16439; }
    { const char * tb_v16440 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16440; }
    { const char * tb_v16441 = "    // раскладка xpad (Xbox и большинство совместимых): кнопки 0 A, 1 B, 2 X, 3 Y, 4 LB, 5 RB, 6 back, 7 start, 8 home, 9 L3, 10 R3;\n"; *(const char * *)tb_grow(v_lines) = tb_v16441; }
    { const char * tb_v16442 = "    // оси 0 lx, 1 ly, 2 lt, 3 rx, 4 ry, 5 rt, 6 крестовина x, 7 крестовина y\n"; *(const char * *)tb_grow(v_lines) = tb_v16442; }
    { const char * tb_v16443 = "    static const int bmap[11] = { TB_PB_A, TB_PB_B, TB_PB_X, TB_PB_Y, TB_PB_L1, TB_PB_R1, TB_PB_SELECT, TB_PB_START, TB_PB_HOME, TB_PB_L3, TB_PB_R3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16443; }
    { const char * tb_v16444 = "    for (int i = 0; i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16444; }
    { const char * tb_v16445 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v16445; }
    { const char * tb_v16446 = "        p->on = tb_pad_fd[i] >= 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16446; }
    { const char * tb_v16447 = "        if (!p->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16447; }
    { const char * tb_v16448 = "        struct { unsigned int time; short value; unsigned char type, number; } e;\n"; *(const char * *)tb_grow(v_lines) = tb_v16448; }
    { const char * tb_v16449 = "        long long got;\n"; *(const char * *)tb_grow(v_lines) = tb_v16449; }
    { const char * tb_v16450 = "        while ((got = read(tb_pad_fd[i], &e, sizeof e)) == (long long)sizeof e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16450; }
    { const char * tb_v16451 = "            int t = e.type & 0x7f;\n"; *(const char * *)tb_grow(v_lines) = tb_v16451; }
    { const char * tb_v16452 = "            if (t == 1 && e.number < 11) p->b[bmap[e.number]] = e.value != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16452; }
    { const char * tb_v16453 = "            else if (t == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16453; }
    { const char * tb_v16454 = "                double v = e.value / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16454; }
    { const char * tb_v16455 = "                if (v < -1) v = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16455; }
    { const char * tb_v16456 = "                switch (e.number) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16456; }
    { const char * tb_v16457 = "                case 0: p->a[TB_PA_LX] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16457; }
    { const char * tb_v16458 = "                case 1: p->a[TB_PA_LY] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16458; }
    { const char * tb_v16459 = "                case 2: p->a[TB_PA_L2] = (v + 1) / 2; p->b[TB_PB_L2] = v > -0.75; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16459; }
    { const char * tb_v16460 = "                case 3: p->a[TB_PA_RX] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16460; }
    { const char * tb_v16461 = "                case 4: p->a[TB_PA_RY] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16461; }
    { const char * tb_v16462 = "                case 5: p->a[TB_PA_R2] = (v + 1) / 2; p->b[TB_PB_R2] = v > -0.75; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16462; }
