    { const char * tb_v16550 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v16550; }
    { const char * tb_v16551 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v16551; }
    { const char * tb_v16552 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v16552; }
    { const char * tb_v16553 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v16553; }
    { const char * tb_v16554 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v16554; }
    { const char * tb_v16555 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v16555; }
