    { const char * tb_v16560 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v16560; }
    { const char * tb_v16561 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v16561; }
    { const char * tb_v16562 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v16562; }
