    { const char * tb_v16564 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v16564; }
    { const char * tb_v16565 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16565; }
    { const char * tb_v16566 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16566; }
    { const char * tb_v16567 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16567; }
