    { const char * tb_v16569 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v16569; }
    { const char * tb_v16570 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16570; }
    { const char * tb_v16571 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16571; }
    { const char * tb_v16572 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16572; }
    { const char * tb_v16573 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v16573; }
