    { const char * tb_v16575 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16575; }
    { const char * tb_v16576 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v16576; }
    { const char * tb_v16577 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16577; }
    { const char * tb_v16578 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v16578; }
    { const char * tb_v16579 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16579; }
    { const char * tb_v16580 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v16580; }
    { const char * tb_v16581 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v16581; }
    { const char * tb_v16582 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v16582; }
    { const char * tb_v16583 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v16583; }
    { const char * tb_v16584 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v16584; }
    { const char * tb_v16585 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v16585; }
    { const char * tb_v16586 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16586; }
    { const char * tb_v16587 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16587; }
    { const char * tb_v16588 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v16588; }
    { const char * tb_v16589 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v16589; }
    { const char * tb_v16590 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16590; }
    { const char * tb_v16591 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v16591; }
    { const char * tb_v16592 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16592; }
    { const char * tb_v16593 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16593; }
    { const char * tb_v16594 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v16594; }
    { const char * tb_v16595 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16595; }
    { const char * tb_v16596 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16596; }
    { const char * tb_v16597 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v16597; }
    { const char * tb_v16598 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16598; }
    { const char * tb_v16599 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v16599; }
    { const char * tb_v16600 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v16600; }
    { const char * tb_v16601 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16601; }
